# -*- coding: utf-8 -*-
"""अध्याय ३, पाद २ — the affix a root takes when a word stands beside it."""

from __future__ import annotations

from src.astadhyayi.sources import register
from src.astadhyayi.tacchila import (
    tacchila_affix, tacchila_heading,
)
from src.astadhyayi.lakara import (
    lakara_for, lat_substitute, sat_samjna,
)
from src.astadhyayi.upapada_krt import (
    bhute_heading, kta_in_present, lit_substitute, nipatana, nistha,
    upapada_affix,
)

# -------------------------------------------------------------------------
# 3.2.1 to 3.2.20 — कर्मण्यण् and the four affixes that cut into it.
# -------------------------------------------------------------------------

_UPAPADA_LINE = (
    'upapada_affix(root, beside=..., role=..., upasarga=..., sense=..., '
    'names_a=..., chandasi=..., causative=..., agent=..., cvi_sense=..., '
    'cvi_ending=..., mantra=..., pada_final=..., attested=..., '
    'jati=..., upamana=..., past=..., wants=...) -> which affix is added where a word stands '
    'beside the root, and by which rule.'
)

_UPAPADA_RULES = {
    "3.2.1": "SETTLED — कर्मण्यण्: कुम्भं करोतीति कुम्भकारः, नगरकारः;\n  काण्डलावः, शरलावः; वेदाध्यायः. The widest rule of the run, and\n  every one of the nineteen after it is an अपवाद to it.\n\nSETTLED — त्रिविधं कर्म, and the vṛtti gives one example of each\n  kind so the rule is seen to reach all three: निर्वर्त्यम् what\n  is brought into being (कुम्भकारः), विकार्यम् what is altered\n  (काण्डलावः), प्राप्यम् what is reached (वेदाध्यायः).\n\nSCAR — अनभिधानात् IS A LIMIT THE RULE DOES NOT STATE. Read as\n  written, 3.2.1 gives a form for every object whatever, and the\n  vṛtti stops it by hand: ग्रामं गच्छति, आदित्यं पश्यति,\n  हिमवन्तं शृणोति — न भवति, अनभिधानात्, because usage has no such\n  word. Ground of the same kind as 3.1.108's. Recorded rather\n  than turned into a condition, since there is no condition to\n  turn it into: the check is against usage, not against the root\n  or the companion.\n\nDEBT — WHICH KĀRAKA THE COMPANION IS, IS PASSED IN. 1.4.49\n  कर्तुरीप्सिततमं कर्म is codified, but it takes the semantic\n  facts asserted OF a participant, not a word: deciding a kāraka\n  needs the whole clause. So the role arrives as an assertion,\n  exactly as 2.3.1 takes it, and the debt is the same one.",
    "3.2.2": "SETTLED — ह्वावामश्च: स्वर्गं ह्वयतीति स्वर्गह्वायः, तन्तून्\n  वयतीति तन्तुवायः, धान्यं मिमीत इति धान्यमायः.\n\nSETTLED — कप्रत्ययस्यापवादः, and asking WHY three roots need\n  naming answers itself: the rule before gives क to every आ-final\n  root, so these three would have had it. The अण् is restored to\n  them by name. The same shape as 3.1.141 naming श्यै — a rule\n  written to survive another rule that already reached its\n  object.\n\nDEBT — ONLY ONE OF THE THREE IS आ-FINAL AS IT STANDS. माङ् is;\n  ह्वेञ् and वेञ् are ए-final in उपदेश and become आ-final only by\n  6.1.45 आदेच उपदेशेऽशिति, which is NOT codified. So the conflict\n  this rule was written to settle can be staged here for मा and\n  not for the other two — 3.2.2 answers for them by naming them,\n  which is the right answer reached without the contest. Found by\n  a test that assumed all three had the shape and failed; the\n  test now asserts the debt instead, and will fail again when\n  6.1.45 is codified.",
    "3.2.3": "SETTLED — आतोऽनुपसर्गे कः: गां ददातीति गोदः, कम्बलदः; and\n  पार्ष्णित्रम्, वरत्रम् with the neuter.\n\nSETTLED — अणोऽपवादः. अनुपसर्ग इति किम्? गोसंदायः, वडवासंदायः —\n  with a preverb attached the general अण् comes back. Whether a\n  preverb stands is 1.4.59 उपसर्गाः क्रियायोगे's question and\n  that rule is codified, so it is asked and not restated; the\n  आ-final test likewise goes to the śivasūtras through 1.1.71.",
    "3.2.4": "SETTLED — सुपि स्थः: समे तिष्ठतीति समस्थः, विषमस्थः.\n\nSETTLED — अत्र योगविभागः कर्तव्यः, and the vṛtti says what the\n  split buys. सुपि alone gives क to any आ-final root after any\n  finished word: द्विपः, पादपः, कच्छपः. स्थः then adds स्था —\n  अनेन भावेऽपि यथा स्यात्, आखूत्थः, शलभोत्थः — so that the affix\n  comes in the ACT sense too, which the first half, giving the\n  agent, would not have reached. A योगविभाग whose second half\n  exists for a sense rather than for a word.",
    "3.2.5": 'SETTLED — तुन्दशोकयोः परिमृजापनुदोः, यथासंख्यम्: तुन्दं\n  परिमार्ष्टीति तुन्दपरिमृज आस्ते; शोकमपनुदतीति शोकापनुदः पुत्रो\n  जातः. Two roots and two words, each with its own.\n\nSETTLED — a vārttika fixes the sense of each: आलस्ये and\n  सुखाहरणे. So अलसः तुन्दपरिमृज उच्यते — the word names the\n  idler and not whoever wipes a belly: तुन्दपरिमार्ज एव अन्यः.\n  The affix carries a judgement the roots do not.\n\nSETTLED — यथासंख्यम् binds the pairs crosswise, so the table\n  holds them as PAIRS rather than as two lists: naming the two\n  roots and the two words separately would let शोक go with\n  परिमृज्, which the rule does not allow.\n\nSETTLED — A SECOND VĀRTTIKA, MISSED ON THE FIRST READING:\n  कप्रकरणे मूलविभुजादिभ्य उपसंख्यानम् — मूलानि विभुजतीति\n  मूलविभुजो रथः, नखमुचानि धनूंषि, काकगुहास्तिलाः, कौ मोदते\n  कुमुदम्. Its members are FINISHED WORDS and not companions, so\n  they are looked up whole as निपातन are: what the vārttika\n  supplies is the word, not a rule for making it.\n  The गणपाठ on disk keys this gaṇa to this sūtra and marks it\n  आकृतिगण, so the membership is read from the corpus and the list\n  is open.\n\nSCAR — HOW IT WAS MISSED, AND HOW IT WAS FOUND. The entry was\n  first read through a pipe that truncated it, and the vārttika\n  sits in the last line. Nothing failed; the rule simply had one\n  fewer provision than the commentary gives. It surfaced only\n  when the गणपाठ was asked which gaṇas it keys to this pāda and\n  named two the code did not have. A commentary entry must be\n  read WHOLE — its length is not knowable in advance, and the\n  most easily lost part of it is the end.',
    "3.2.6": "SETTLED — प्रे दाज्ञः: सर्वं प्रददातीति सर्वप्रदः; पन्थानं\n  प्रजानातीति पथिप्रज्ञः.\n\nSETTLED — अणोऽपवादः, and सोपसर्गार्थ आरम्भः: the rule exists\n  ONLY because 3.2.3 had shut preverbs out. दा and ज्ञा are\n  आ-final and would have had क already; what they could not have\n  had is क WITH प्र. The same shape as 3.1.72 against 3.1.71 —\n  a rule whose whole work is to let back in what the rule before\n  it excluded.\n\nSETTLED — प्र इति किम्? गोसंदायः.",
    "3.2.7": "SETTLED — समि ख्यः: गां संचष्ट इति गोसंख्यः.\n\nSETTLED — अणोऽपवादः, and सोपसर्गार्थ आरम्भः as at 3.2.6.\n\nSETTLED — ख्या is not a root of the dhātupāṭha at all: it is\n  what चक्षिङ् becomes by 2.4.54 चक्षिङः ख्याञ्, which is\n  codified. The vṛtti writes the derivation from चष्टे, and the\n  rule names the substitute rather than the root it replaces.",
    "3.2.8": "SETTLED — गापोष्टक्: शक्रं गायतीति शक्रगः, सामगः, and the\n  feminines शक्रगी, सामगी.\n\nSETTLED — कस्यापवादः — an exception to 3.2.3 and not to 3.2.1,\n  since 3.2.3 had already reached these two. अनुपसर्ग इत्येव,\n  carried down: शक्रसंगायः.\n\nDEBT — and only पा is आ-final as it stands. गै is ऐ-final in\n  उपदेश and reaches the shape by 6.1.45 आदेच उपदेशेऽशिति, which\n  is not codified — the same debt 3.2.2 records, and the reason\n  both rules name their roots rather than relying on the shape.\n\nSCOPE — a vārttika holds पा to two drinks: सुरापः, शीधुपः. And\n  it asks both questions. सुराशीध्वोरिति किम्? क्षीरपा ब्राह्मणी\n  — of milk the affix does not come. पिबतेरिति किम्? सुरां\n  पातीति सुरापा — where the root is the one meaning 'protect'\n  and not the one meaning 'drink', the same two syllables give a\n  different word. Recorded.",
    "3.2.9": "SETTLED — हरतेरनुद्यमनेऽच्: अंशं हरतीति अंशहरः, रिक्थहरः.\n  अणोऽपवादः. उद्यमनम् उत्क्षेपणम् — the lifting up.\n\nSETTLED — अनुद्यमन इति किम्? भारहारः. Of carrying a load the\n  general अण् stands, and 3.2.10 then gives the अच् back for the\n  very sense refused here, where an age is meant.",
    "3.2.10": "SETTLED — वयसि च: अस्थिहरः श्वा, कवचहरः क्षत्रियकुमारः.\n  कालकृता शरीरावस्था यौवनादिर्वयः — the body's state as time\n  makes it.\n\nSETTLED — उद्यमनार्थोऽयम् आरम्भः: this rule exists FOR the\n  sense 3.2.9 refused. A prohibition and its exception written\n  one after the other, so the pair has to be read as a pair.",
    "3.2.11": "SETTLED — आङि ताच्छील्ये: पुष्पाहरः, फलाहरः.\n\nSETTLED — ताच्छील्यं तत्स्वभावता, being that by nature. The\n  vṛtti glosses it by the doing and not by the aim: picking\n  flowers as one's way, without an eye to what comes of it.\n  ताच्छील्य इति किम्? भाराहारः.",
    "3.2.12": "SETTLED — अर्हः: पूजामर्हतीति पूजार्हा, गन्धार्हा, मालार्हा.\n  अणोऽपवादः.\n\nSETTLED — स्त्रीलिङ्गे विशेषः: the two affixes are told apart\n  in the FEMININE, which is why all three of the vṛtti's\n  examples are feminine. An affix chosen for what it does to a\n  form two rules away, as 3.2.16's will be.",
    "3.2.13": "SETTLED — स्तम्बकर्णयो रमिजपोः, यथासंख्यम्: स्तम्बे रमत इति\n  स्तम्बेरमो हस्ती; कर्णे जपतीति कर्णेजपः सूचकः.\n\nSETTLED — THE COMPANION HERE IS A सुबन्त AND NOT AN OBJECT, and\n  the vṛtti reasons it out rather than asserting it:\n  रमेरकर्मकत्वात्, जपेः शब्दकर्मकत्वात् कर्म न संभवति — रम् takes\n  no object at all, and what जप् takes for an object is a sound,\n  so कर्मणि could not have been meant here and सुपि is read down\n  instead. A condition settled by what the two roots can do.\n\nSETTLED — यथासंख्यम् again, held as pairs for the reason given\n  at 3.2.5: कर्ण must not go with रम्.",
    "3.2.14": "SETTLED — शमि धातोः संज्ञायाम्: शंकरः, शंभवः, शंवदः, शंवसः.\n\nSETTLED — धातुग्रहणं कृञो हेत्वादिषु टप्रतिषेधार्थम्. The vṛtti\n  asks why धातोः is stated when it is already running, and\n  answers that it is to keep 3.2.20's ट off कृ HERE: so that\n  शंकरा नाम परिव्राजिका is formed with this अच् and not with\n  that ट. A word repeated in one rule to fence off another —\n  the same device as 3.1.141's श्यै, seen from the other side.",
    "3.2.15": 'SETTLED — अधिकरणे शेतेः: खे शेत इति खशयः, गर्तशयः. सुपीति\n  संबध्यते, so the companion is a finished word and the rule\n  adds that it be the place.\n\nSETTLED — FOUR VĀRTTIKAS, NOW CODIFIED RATHER THAN RECORDED, and\n  three of them re-read: the first pass had them from a truncated\n  view of the entry and got their shape wrong.\n  पार्श्वादिषूपसंख्यानम् is a GAṆA and not पार्श्वात् संज्ञायाम् —\n  पार्श्वशयः, उदरशयः, पृष्ठशयः — and the गणपाठ on disk holds its\n  five members, keyed to this very sūtra. What the vārttika buys\n  is that the companion need NOT be the place: पार्श्वाभ्यां शेते\n  is instrumental.\n  उत्तानादिषु कर्तृषु is a vārttika of its own over the same gaṇa,\n  taking the companion as the AGENT — उत्तानः शेते उत्तानशयः,\n  अवमूर्धा शेते अवमूर्धशयः. So the rows share the corpus list and\n  differ by role, which is how the vṛtti divides it.\n  दिग्धसहपूर्वाच्च gives दिग्धसहशयः.\n  गिरौ डश्छन्दसि gives गिरिशः — the one of the four that changes\n  the AFFIX rather than what it is added after, and it holds in\n  the Veda only.\n\nSETTLED — found by asking the गणपाठ which gaṇas it keys to this\n  pāda. It named two, पार्श्वादि here and मूलविभुजादि at 3.2.5,\n  and the code had neither.',
    "3.2.16": "SETTLED — चरेष्टः: कुरुषु चरतीति कुरुचरः, मद्रचरः.\n\nSETTLED — WHY A DIFFERENT AFFIX FROM 3.2.15's, when both put\n  the same sound after the root: प्रत्ययान्तरकरणं ङीबर्थम् — so\n  that the feminine takes ङीप्, कुरुचरी, मद्रचरी. An affix\n  chosen not for the form it makes here but for what a rule in\n  adhyāya 4 will do with its marker. The second such choice in\n  five rules, after 3.2.12.",
    "3.2.17": "SETTLED — भिक्षासेनादायेषु च: भिक्षाचरः, सेनाचरः, आदायचरः.\n\nSETTLED — अनधिकरणार्थ आरम्भः: the rule exists because none of\n  the three is a place, which is the one thing 3.2.16 required.\n  Same root, same affix, a companion of another kind.",
    "3.2.18": "SETTLED — पुरोऽग्रतोऽग्रेषु सर्तेः: पुरःसरः, अग्रतःसरः,\n  अग्रेसरः.",
    "3.2.19": "SETTLED — पूर्वे कर्तरि: पूर्वः सरतीति पूर्वसरः.\n\nSETTLED — कर्तरीति किम्? पूर्वं देशं सरतीति पूर्वसारः. One\n  word, one root, and the KĀRAKA is the whole of the difference\n  between the two forms — which is as sharp a demonstration as\n  this pāda gives that the role has to be an input and cannot be\n  read off the companion. 3.2.1's debt, shown rather than\n  argued.",
    "3.2.21": "SETTLED — दिवाविभानिशाप्रभाभास्कारान्तानन्तादिबहुनान्दीकिं…\n  दिवाकरः, विभाकरः, निशाकरः, प्रभाकरः, भास्करः, अन्तकरः,\n  किंकरः, अहस्करः, धनुष्करः — twenty-seven companions for कृ.\n\nSETTLED — अहेत्वाद्यर्थ आरम्भः: the rule exists for the senses\n  3.2.20 did NOT cover, which is why it names its companions one\n  by one instead of naming a sense. An अपवाद defined by what the\n  rule before it left out.\n\nSETTLED — BOTH कर्मणि AND सुपि run down into it: कर्मणि सुपीति\n  च द्वयमप्यनुवर्तते, तत्र यथायोगं सम्बन्धः — each member takes\n  whichever of the two fits it, and the vṛtti points at the one\n  that is a place, दिवाशब्दोऽधिकरणवचनः. Codified with the wider\n  of the two, since सुपि admits every role including कर्मन्.\n\nSCOPE — भास्करः is a निपातन for its स्: सकारस्य निपातनाद्\n  विसर्जनीयजिह्वामूलीयौ न भवतः, the two sound-changes that would\n  otherwise have applied are simply not made. Recorded; the rules\n  that would make them are in adhyāya 8 and this run does not\n  reach them.\n\nSCOPE — a vārttika gives four of the twenty-seven अच् instead —\n  किंयत्तद्बहुषु कृञोऽज्विधानम्, for the feminines किंकरा, यत्करा,\n  तत्करा, बहुकरा. Recorded WITHOUT a row, because the vṛtti\n  itself declines to settle it: अथवाजादिषु पाठः करिष्यते, or\n  else they will be read into the अजादि list. Two routes offered\n  and neither chosen, so codifying one would be deciding what the\n  commentary left open.",
    "3.2.22": "SETTLED — कर्मणि भृतौ: कर्म करोतीति कर्मकरः, भृतक इत्यर्थः — a\n  hired labourer. भृतिर्वेतनम्, कर्मनिर्वेशः, wages.\n  भृताविति किम्? कर्मकारः.\n\nSETTLED — कर्मणीति स्वरूपग्रहणम्, AND THIS IS THE POINT OF THE\n  RULE. Here कर्मन् is the WORD itself standing beside — कर्मशब्द\n  उपपदे कर्मवाचिनि — not the kāraka that the very same word meant\n  at 3.2.1 twenty-one rules back. One term read two ways inside\n  one pāda, and the difference is not marked in the text: it is\n  read off what the rule could sensibly mean. Codified by naming\n  कर्मन् in the companion list rather than in the role, so the\n  two readings cannot be confused by the code either.",
    "3.2.23": "SETTLED — न शब्दश्लोककलहगाथावैरचाटुसूत्रमन्त्रपदेषु: शब्दकारः,\n  श्लोककारः, कलहकारः, गाथाकारः, वैरकारः, चाटुकारः, सूत्रकारः,\n  मन्त्रकारः, पदकारः.\n\nSETTLED — हेत्वादिषु प्राप्तः प्रतिषिध्यते: what is refused is\n  3.2.20's ट in the three senses. The ONLY प्रतिषेध of the run.\n\nSETTLED — AND IT DOES NOT THEREBY GOVERN THESE WORDS. What they\n  take is 3.2.1's अण्, which is why every form the vṛtti gives\n  here ends in -कारः and not in -करः. So the answer names 3.2.1\n  and carries 3.2.23 in `blocked_by` — the decision 2.3.72 and\n  2.3.50 settled, that the rule which SUPPLIES the case answers\n  and not the rule that excepted it. Where a refusal leaves\n  nothing at all the refusal does name itself, since refusing is\n  then the whole of what the rule did; that is not this case.",
    "3.2.24": "SETTLED — स्तम्बशकृतोरिन्: स्तम्बकरिर्व्रीहिः, शकृत्करिर्वत्सः.\n\nSETTLED — व्रीहिवत्सयोरिति वक्तव्यम् is a vārttika, and it is\n  codified as a CONDITION rather than merely recorded, because\n  the vṛtti's own counter-example turns on it: व्रीहिवत्सयोरिति\n  किम्? स्तम्बकारः, शकृत्कारः. A vārttika that changes the output\n  has to be in the table or the counter cannot be tested.\n\nSETTLED — the condition is on what the FINISHED WORD denotes, a\n  different question from the sense of the act, and it needed its\n  own field. See 3.2.25.",
    "3.2.25": "SETTLED — हरतेर्दृतिनाथयोः पशौ: दृतिं हरतीति दृतिहरिः पशुः,\n  नाथहरिः पशुः. पशाविति किम्? दृतिहारः, नाथहारः.\n\nSETTLED — A SEVENTH FIELD-NAME COLLISION, found here. `sense`\n  was carrying two different questions at once: the sense of the\n  ACT (उद्यमन at 3.2.9, वयस् at 3.2.10, भृति at 3.2.22) and what\n  the finished WORD denotes (पशु here, व्रीहि at 3.2.24). This\n  rule needs both at the same time — पशौ is its own condition,\n  and उद्यमन is what keeps 3.2.9's अच् off दृतिहारः, since\n  carrying a waterskin IS lifting. With one field the two masked\n  each other and दृतिहारः came out as *दृतिहरः. Split into\n  `names_a`.",
    "3.2.26": "SETTLED — फलेग्रहिरात्मम्भरिश्च, and both words are निपातन:\n  फलशब्दस्य उपपदस्यैकारान्तत्वम् इन्प्रत्ययश्च ग्रहेर्निपात्यते —\n  the ए-final shape of फल AND the इन् after ग्रह् are both fixed;\n  आत्मशब्दस्योपपदस्य मुमागम इन्प्रत्ययश्च भृञो निपात्यते — the\n  मुम् augment on आत्म and the इन् after भृ. फलेग्रहिर्वृक्षः,\n  आत्मम्भरिः.\n\nSETTLED — given its own entry point, as the seventeen निपातन of\n  3.1.96–132 were. A table that derived these would be pretending\n  to a derivation the grammar declines to give.\n\nSETTLED — अनुक्तसमुच्चयार्थश्चकारः: the च gathers in what the\n  sūtra did not name, and the vṛtti adds कुक्षिम्भरिः and\n  उदरम्भरिः by it. So the two words stated are not the whole of\n  the rule, and the entry point holds all four with a note saying\n  which two came from the च.",
    "3.2.27": "SETTLED — छन्दसि वनसनरक्षिमथाम्: ब्रह्मवनिम्, गोसनिम्, पथिरक्षी,\n  हविर्मथीनाम् — four roots taking इन्, each with the Vedic\n  passage the vṛtti cites for it (Taittirīya and Śaunaka\n  Saṃhitās and the Ṛgveda).\n\nSETTLED — छन्दसि विषये, so the rule holds in the Veda and not\n  outside it. Codified as a one-way condition: a Vedic rule must\n  not answer outside the Veda, but the rules that say nothing\n  about it still answer inside it — the Veda has the ordinary\n  grammar too, and only adds to it.",
    "3.2.29": "SETTLED — नासिकास्तनयोर्ध्माधेटोः: नासिकन्धमः, नासिकन्धयः,\n  स्तनन्धयः. धेटष्टित्त्वात् स्त्रियां ङीप्: स्तनन्धयी.\n\nSETTLED — यथासंख्यम् IS REFUSED HERE, AND THE REFUSAL IS READ\n  OFF THE WORDING. यथासंख्यमत्र नेष्यते: स्तने धेटः — स्तन goes\n  with धेट् alone — नासिकायां तु ध्मश्च धेटश्च, but नासिका takes\n  both. So the licensed set is neither the one-to-one pairing\n  3.2.5 and 3.2.13 required nor the full product 3.2.30 allows.\n  What licenses the departure is लक्षणव्यभिचारचिह्नाद्\n  अल्पाच्तरस्यापूर्वनिपातनाल्लभ्यते: the shorter word would stand\n  first by 2.2.34 अल्पाच्तरम्, and its NOT standing first is the\n  sign that the ordinary reading is off. A commentary reading a\n  rule's intent out of the order of its own words.\n\nSETTLED — codified with a `pairs` field naming the three\n  combinations. यथासंख्यम् had been two special cases keyed on\n  sūtra id; this rule needs a set that is neither paired nor\n  full, so the pairing became a field and the special cases went.",
    "3.2.30": "SETTLED — नाडीमुष्ट्योश्च: नाडिन्धमः, मुष्टिन्धमः, नाडिन्धयः,\n  मुष्टिन्धयः — here every combination stands.\n\nSETTLED — and the same kind of sign, read off a different rule:\n  घ्यन्तस्यापूर्वनिपातो लक्षणव्यभिचारचिह्नम्, तेन\n  संख्यातानुदेशो न भवति. The घि-final word not standing first is\n  what says संख्यातानुदेश — the counting-off — does not apply.\n\nSCOPE — अनुक्तसमुच्चयार्थश्चकारः: the च gathers in घटि, खारि and\n  वात, which the sūtra does not name — घटिन्धमः, खारिन्धयः,\n  वातन्धमः पर्वतः. Codified into the list, since the vṛtti\n  supplies the members outright rather than leaving the class\n  open as 3.2.33's प्रस्थादि does.",
    "3.2.31": 'SETTLED — उदि कूले रुजिवहोः: कूलमुद्रुजो रथः, कूलमुद्वहः. The\n  preverb is named, so it is a condition and not a bar — unlike\n  3.2.3 and 3.2.8, which refuse one.',
    "3.2.32": 'SETTLED — वहाभ्रे लिहः: वहं लेढीति वहंलिहो गौः, अभ्रंलिहो\n  वायुः.',
    "3.2.33": 'SETTLED — परिमाणे पचः: प्रस्थंपचा स्थाली, द्रोणम्पचः,\n  खारिम्पचः कटाहः.\n\nSCOPE — परिमाणं प्रस्थादि, an आकृतिगण: the class is given by\n  its first member and is open, so the three named are examples\n  and not the whole. Recorded as the पचादि of 3.1.134 was — an\n  open class the corpus itself marks open, not a list to be\n  completed by hand.',
    "3.2.34": 'SETTLED — मितनखे च: मितम्पचा ब्राह्मणी, नखम्पचा यवागूः.\n\nSETTLED — अपरिमाणार्थ आरम्भः: the rule exists because neither\n  word is a measure, which is the one thing 3.2.33 required. The\n  same shape as 3.2.17 against 3.2.16 — same root, same affix, a\n  companion of another kind.',
    "3.2.35": 'SETTLED — विध्वरुषोस्तुदः: विधुन्तुदो राहुः, अरुन्तुदः.',
    "3.2.36": "SETTLED — असूर्यललाटयोर्दृशितपोः, यथासंख्यम्: असूर्यम्पश्या\n  राजदाराः, ललाटन्तप आदित्यः. Bound crosswise, unlike 3.2.29\n  seven rules back — so the pāda states both readings within one\n  run and the code has to distinguish them by rule and not by a\n  default.\n\nSETTLED — असूर्य इति चासमर्थसमासोऽयम्: the न does not go with\n  सूर्य at all but with दृश् — सूर्यं न पश्यन्तीति — so the\n  compound is 'not-seeing the sun' and not 'non-sun'. गुप्तिपरं\n  चैतत्, the word is about seclusion: एवं नाम गुप्ता\n  यदपरिहार्यदर्शनं सूर्यमपि न पश्यन्तीति — so secluded that they\n  do not see even the sun, which one cannot avoid seeing.",
    "3.2.37": "SETTLED — उग्रम्पश्येरम्मदपाणिन्धमाश्च, and all three are\n  निपातन: उग्रम्पश्यः, इरम्मदः, पाणिन्धमाः पन्थानः.\n\nSETTLED — given its own entry point beside 3.2.26's, for the\n  same reason. पाणिन्धम shows why plainly: पाणयो ध्मायन्त\n  एष्विति — the companion is not the object at all but the place,\n  so no rule of the खश् run could have reached it and the fixing\n  is the whole of its authority.",
    "3.2.38": "SETTLED — प्रियवशे वदः खच्: प्रियंवदः, वशंवदः. खकारो मुमर्थः.\n\nSETTLED — चकारः खचि ह्रस्वः इति विशेषणार्थः: the च is written\n  so that 6.4.94 can name this affix — a mark placed in one rule\n  for a rule four adhyāyas away, as 3.1.133's च was.\n\nSETTLED — प्रत्ययान्तरकरणमुत्तरार्थम्: a DIFFERENT affix from\n  the खश् of the rules before, chosen for the sake of the rules\n  after. The third time this pāda picks an affix for what a later\n  rule will do with it, after 3.2.12 and 3.2.16.\n\nSCOPE — four vārttikas: गमेः सुप्युपसंख्यानम् (मितंगमो हस्ती,\n  मितंगमा हस्तिनी), विहायसो विह च (विहंगमः), खच्च डिद् वा\n  (विहंगः), डे च विहायसो विहादेशः (विहगः). Recorded.",
    "3.2.39": 'SETTLED — द्विषत्परयोस्तापेः: द्विषन्तपः, परन्तपः.\n\nSETTLED — तप दाहे चुरादिः and तप संतापे भ्वादिः, द्वयोरपि\n  ग्रहणम्: both roots written alike are meant, so unlike 3.2.28\n  this rule does NOT turn on the causative. Two rules of one pāda\n  taking opposite views of the same ambiguity, each stated.\n\nSETTLED — द्विषत्परयोरिति द्वितकारको निर्देशः, तेन स्त्रियां न\n  भवति: the spelling with two त् is what keeps the feminine out —\n  द्विषतीं तापयति gives द्विषतीतापः and not *द्विषतीतपः. A\n  condition carried by an orthographic detail of the sūtra.',
    "3.2.40": 'SETTLED — वाचि यमो व्रते: वाचंयम आस्ते, one under a vow of\n  silence. व्रत इति शास्त्रितो नियम उच्यते — a restraint laid\n  down by rule, not any resolve. व्रत इति किम्? वाग्यामः.',
    "3.2.41": 'SETTLED — पूःसर्वयोर्दारिसहोः, यथासंख्यम्: पुरं दारयति\n  पुरंदरः; सर्वंसहो राजा.\n\nSCOPE — भगे च दारेरिति वक्तव्यम्: भगन्दरः. Recorded.',
    "3.2.42": 'SETTLED — सर्वकूलाभ्रकरीषेषु कषः: सर्वंकषः खलः, कूलंकषा नदी,\n  अभ्रंकषो गिरिः, करीषंकषा वात्या.',
    "3.2.43": "SETTLED — मेघर्तिभयेषु कृञः: मेघंकरः, ऋतिंकरः, भयंकरः.\n\nSETTLED — उपपदविधौ भयादिग्रहणं तदन्तविधिं प्रयोजयति: naming\n  भय in an उपपद rule brings 1.1.72 येन विधिस्तदन्तस्य into\n  play, so a word ENDING in भय is reached as well — अभयंकरः.\n  1.1.72 is codified, so it is ASKED rather than approximated\n  with a suffix test here, and the reuse is declared. The vṛtti\n  flags this rule for it specifically, so it is not extended to\n  the run at large: 3.2.42's सर्व and कूल carry no such note.",
    "3.2.44": "SETTLED — क्षेमप्रियमद्रेऽण् च: क्षेमकारः and क्षेमंकरः,\n  प्रियकारः and प्रियंकरः, मद्रकारः and मद्रंकरः. चकारात् खच्च —\n  BOTH affixes stand, so the rule gives two forms for each word.\n  Codified as one row carrying `also`, as 3.1.147 was.\n\nSETTLED — वेति वक्तव्ये पुनरण्ग्रहणं हेत्वादिषु\n  टप्रतिषेधार्थम्: वा would have said 'optionally' in fewer\n  syllables, and अण् is named instead so as to keep 3.2.20's ट\n  out. The second rule of this pāda to repeat a word for that\n  purpose, after 3.2.14's धातुग्रहण — and the two together show\n  the device is a habit of the text and not a one-off.",
    "3.2.45": 'SETTLED — आशिते भुवः करणभावयोः: आशितो भवत्यनेन आशितंभव\n  ओदनः, the rice BY WHICH one is fed; and आशितस्य भवनम्\n  आशितंभवं वर्तते, the being-fed itself. One rule, two senses,\n  both named in it.\n\nSETTLED — अत्र सुपीत्युपतिष्ठते: सुपि and not कर्मणि is what\n  stands here, so the companion is any finished word.',
    "3.2.46": "SETTLED — संज्ञायां भृतॄवृजिधारिसहितनिषु: विश्वम्भरा,\n  वसुन्धरा, रथंतरं साम, पतिंवरा कन्या, शत्रुंजयो हस्ती,\n  युगंधरः पर्वतः, शत्रुंसहः, शत्रुंतपः, अरिंदमः.\n  संज्ञायामिति किम्? कुटुम्बभारः.\n\nSETTLED — कर्मणीति सुपीति च प्रकृतं संज्ञावशाद् यथासंभवं\n  संबध्यते: both run down, and which applies is settled by what\n  the NAME will bear. The third time in this pāda the two are\n  read together यथायोगम्, after 3.2.21 and 3.2.45 — so it is the\n  pāda's ordinary way and not an exception.",
    "3.2.47": 'SETTLED — गमश्च: सुतंगमो नाम, यस्य पुत्रः सौतंगमिः.\n  योगविभाग उत्तरार्थः — split from 3.2.46 for the sake of the\n  rule after, the same device as 3.1.147.',
    "3.2.28": "SETTLED — एजेः खश्: अङ्गमेजयति अङ्गमेजयः, जनमेजयः. ण्यन्तात्,\n  from the CAUSATIVE stem and not from the bare root, which is\n  why the rule takes a separate condition rather than a sense.\n\nSETTLED — THE TWO MARKERS DO TWO DIFFERENT JOBS, and the vṛtti\n  separates them: खकारो मुमर्थः — the ख is there for the मुम्\n  augment, which is what gives अङ्गम्- its म्; शकारः\n  सार्वधातुकसंज्ञार्थः — the श makes the affix सार्वधातुक by\n  3.4.113 तिङ्शित्सार्वधातुकम्. 3.4.113 IS codified, and it is\n  cited here rather than declared as reuse, because nothing in\n  this module calls it: what the marker buys happens downstream\n  of the affix, not in choosing it. `reuses` is for where code\n  runs code.",
    "3.2.20": "SETTLED — कृञो हेतुताच्छील्यानुलोम्येषु, and the vṛtti glosses\n  all three: हेतुरैकान्तिकं कारणम् — शोककरी कन्या, यशस्करी\n  विद्या; ताच्छील्यं तत्स्वभावता — श्राद्धकरः, पातकरः;\n  आनुलोम्यम् अनुकूलता — प्रैषकरः, वचनकरः.\n\nSETTLED — एतेष्विति किम्? कुम्भकारः, नगरकारः. Outside the three\n  senses 3.2.1's अण् stands, so the run closes by handing the\n  ground back to the rule it opened with.",
    "3.2.48": 'SETTLED — अन्तात्यन्ताध्वदूरपारसर्वानन्तेषु डः: अन्तगः, अध्वगः,\n  दूरगः, पारगः, सर्वगः. डकारः टिलोपार्थः — the ड is marked so\n  that the टि goes.\n\nSETTLED — संज्ञायामिति नानुवर्तते. The संज्ञा condition running\n  through 3.2.46 and 3.2.47 STOPS here, and it is the commentary\n  that stops it: nothing in the text says so. Worth marking,\n  because the codification has no way to represent anuvrtti at\n  all — every row states its own conditions, so an अनुवृत्ति that\n  ends is simply a condition not written, and this note is the\n  only record that a choice was made rather than a line missed.\n\nSCOPE — five vārttikas add members: सर्वत्रपन्नयोरुपसंख्यानम्,\n  उरसो लोपश्च (उरगः), सुदुरोरधिकरणे (सुगः, दुर्गः), निरो देशे\n  (निर्गो देशः). Codified into the list. And then the vṛtti\n  declines to close it: डप्रकरणेऽन्येष्वपि दृश्यत इति,\n  स्त्र्यगारगः, ग्रामगः, गुरुतल्पगः — the rule reaches words no\n  list holds, and the codification does not pretend otherwise.',
    "3.2.49": 'SETTLED — आशिषि हनः: तिमिं वध्यात् तिमिहः, शत्रुहः.\n  आशिषीति किम्? शत्रुघातः.\n\nSCOPE — three vārttikas give अण् instead after a different\n  preverb, with a substitution for the final:\n  दारावाहनोऽणन्तस्य च टः संज्ञायाम् (दार्वाघाटः), चारौ वा\n  (चार्वाघाटः beside चार्वाघातः), कर्मणि समि च (वर्णसंघाटः beside\n  वर्णसंघातः). All three turn on a sound-change downstream of\n  choosing the affix, so they are recorded and not tabled.',
    "3.2.50": 'SETTLED — अपे क्लेशतमसोः: क्लेशापहः पुत्रः, तमोऽपहः सूर्यः.\n\nSETTLED — अनाशीरर्थ आरम्भः: the rule exists to reach the sense\n  3.2.49 did NOT cover. The third time this pāda writes a rule to\n  reach past the condition of the one before it — after 3.2.10\n  against 3.2.9 and 3.2.34 against 3.2.33 — and by now the shape\n  is a habit of composition rather than a coincidence.',
    "3.2.51": "SETTLED — कुमारशीर्षयोर्णिनिः: कुमारघाती, शीर्षघाती.\n\nSETTLED — निपातनाच्छिरसः शीर्षभावः: शिरस् becomes शीर्ष by this\n  sūtra's own fixing and by no rule. Recorded and not codified —\n  the rule chooses an affix, and what the companion's shape\n  becomes is another matter.",
    "3.2.52": 'SETTLED — लक्षणे जायापत्योष्टक्: जायाघ्नो ब्राह्मणः, पतिघ्नी\n  वृषली — one who bears the MARK of it, an ill omen.\n\nSETTLED — TWO READINGS, NEITHER CHOSEN: लक्षणवति कर्तरि, the\n  agent who HAS the mark; अथ वा लक्षणे द्योत्ये, the mark being\n  what the word conveys. Both give the same forms, so the\n  condition is taken as written — लक्षणे — and this note records\n  that the two differ in what they say the word is doing, not in\n  what it produces.',
    "3.2.53": 'SETTLED — अमनुष्यकर्तृके च: जायाघ्नस्तिलकालकः, पतिघ्नी पाणिरेखा,\n  श्लेष्मघ्नं मधु, पित्तघ्नं घृतम् — a mole, a line of the palm,\n  honey, ghee. अमनुष्यकर्तृक इति किम्? आखुघातः शूद्रः.\n\nDEBT — the vṛtti asks its own hardest question here: इह कस्माद्\n  न भवति चौरघातो हस्ती? An elephant is no man, so why is the form\n  not made? And it answers from OUTSIDE this pāda — कृत्यल्युटो\n  बहुलम् (3.3.113) इति बहुलवचनाद् अण् भवति. 3.3.113 is NOT\n  codified, so the answer is recorded and cannot yet be run; when\n  that rule lands, this becomes reachable.',
    "3.2.54": "SETTLED — शक्तौ हस्तिकपाटयोः: हस्तिनं हन्तुं शक्तो हस्तिघ्नो\n  मनुष्यः; कपाटघ्नश्चौरः, a thief who breaks a door.\n  शक्ताविति किम्? विषेण हस्तिनं हन्ति हस्तिघातः.\n\nSETTLED — मनुष्यकर्तृकार्थ आरम्भः is the vṛtti's REASON for the\n  rule: it reaches the human agent 3.2.53 shut out. But the rule\n  states शक्तौ and not मनुष्यकर्तृके, so what is codified is the\n  condition written and not the reason for writing it. The pair\n  3.2.53/3.2.54 has to be read together: the first excludes the\n  human agent, the second reaches him by another road.",
    "3.2.55": 'SETTLED — पाणिघताडघौ शिल्पिनि, and both are निपातन: तस्मिंश्च\n  परतो हन्तेष्टिलोपो घत्वं च निपात्यते — the affix, the loss of\n  the टि and the घ, all three fixed. पाणिघः, ताडघः.\n  शिल्पिनीति किम्? पाणिघातः, ताडघातः.\n\nSCOPE — राजघ उपसंख्यानम्: राजानं हन्ति राजघः, added by a\n  vārttika and NOT held to a craftsman. Codified with the other\n  two, since the vārttika supplies the word outright as the sūtra\n  does.',
    "3.2.56": 'SETTLED — आढ्य…प्रियेषु च्व्यर्थेष्वच्वौ कृञः करणे ख्युन्:\n  अनाढ्यमाढ्यं कुर्वन्त्यनेन आढ्यंकरणम्, सुभगंकरणम्, नग्नंकरणम्.\n\nSETTLED — TWO CONDITIONS ON THE COMPANION, AND THE VṚTTI ASKS\n  AFTER EACH SEPARATELY. च्व्यर्थेष्विति किम्? आढ्यं तैलेन\n  कुर्वन्ति, अभ्यञ्जयन्तीत्यर्थः — merely anointing, where nothing\n  BECOMES what it was not. अच्वाविति किम्? आढ्यीकुर्वन्त्यनेन —\n  where the च्वि is actually there. The rule wants the च्वि\n  MEANING without the च्वि AFFIX, and they are two fields in the\n  code because the commentary treats them as two questions.\n\nSETTLED — AN ARGUMENT ABOUT WHAT A प्रतिषेध BUYS. ननु च ख्युना\n  मुक्ते ल्युटा भवितव्यम्, न च ल्युटः ख्युनश्च विशेषोऽस्ति, तत्र\n  किं प्रतिषेधेन? — if ख्युन् is refused, ल्युट् will come, and\n  the two are indistinguishable, so the refusal buys nothing.\n  एवं तर्हि प्रतिषेधसामर्थ्यात् ख्युन्यसति ल्युडपि न भवति, तेन\n  ल्युटोऽप्ययमर्थतः प्रतिषेधः: the very FORCE of refusing keeps\n  ल्युट् out as well. उत्तरार्थश्च च्विप्रतिषेधः क्रियते.',
    "3.2.57": 'SETTLED — कर्तरि भुवः खिष्णुच्खुकञौ, TWO affixes both standing:\n  आढ्यंभविष्णुः and आढ्यंभावुकः, सुभगंभविष्णुः and सुभगंभावुकः.\n  One row carrying `also`, as 3.1.147, 3.2.44 and 3.2.60 are.\n\nSETTLED — कर्तरीति किम्? करणे मा भूत्. THE AGENT here where\n  3.2.56 wanted the instrument, and that is the whole difference\n  between the two: same companions, same two च्वि conditions, a\n  different kāraka and so a different affix.\n  च्व्यर्थेष्वित्येव: आढ्यो भविता. अच्वावित्येव: आढ्यीभविता.\n\nSCOPE — the entry closes with a verse arguing from the ACCENT why\n  the इ of इष्णुच् is written: उदात्तत्वाद् भुवः सिद्धम्\n  इकारादित्वम् इष्णुचः, नञस्तु स्वरसिद्ध्यर्थम्. Accent is a\n  thread this project has open, so this is recorded, not used.',
    "3.2.58": 'SETTLED — स्पृशोऽनुदके क्विन्: घृतस्पृक्, मन्त्रस्पृक्, जलस्पृक्.\n  अनुदक इति किम्? उदकस्पर्शः. The ONLY rule of this pāda that\n  names a companion in order to REFUSE it rather than require it,\n  which is why the table needed a field for it.\n\nSETTLED — WHY THE COMPANION IS ANY सुबन्त AND NOT THE OBJECT, and\n  the vṛtti raises the objection against itself: ननु च\n  सकर्मकत्वात् स्पृशेः कर्मैवोपपदं प्राप्नोति? नैष दोषः —\n  कर्तरीति पूर्वसूत्रादनुवर्तते, तत्कर्तृप्रचयार्थं विज्ञायते,\n  सुबन्तमात्रे चोपपदे कर्तृप्रचयो लभ्यते. The examples bear it\n  out: मन्त्रेण स्पृशन्ति मन्त्रस्पृक् is an instrument, not an\n  object.\n\nSETTLED — नकारः क्विन्प्रत्ययस्य कुः (8.2.62) इति विशेषणार्थः —\n  a marker written for a rule five adhyāyas on. Cited and not\n  called: 8.2.62 acts on the finished form, not on this choice.',
    "3.2.59": "SETTLED — ऋत्विग्दधृक्स्रग्दिगुष्णिगञ्चुयुजिक्रुञ्चां च, AND THE\n  SŪTRA IS OF TWO KINDS AT ONCE. ऋत्विगादयः पञ्चशब्दाः\n  क्विन्प्रत्ययान्ता निपात्यन्ते — five WORDS fixed outright;\n  अपरे त्रयो धातवो निर्दिश्यन्ते — three ROOTS named, taking the\n  affix by rule. So it is codified in BOTH places, and it is the\n  first sūtra of the project that has to be.\n\nSETTLED — the five, each with what is fixed in it: ऋत्विक् —\n  and the vṛtti offers three derivations and chooses none,\n  रूढिरेषा यथाकथंचिदनुगन्तव्या, the word is settled and the\n  derivation may be taken however one likes; दधृक् (affix,\n  reduplication, final accent); स्रक् (affix and the अम् augment);\n  दिक्; उष्णिक् (affix, loss of the preverb's end, and ष).\n\nSETTLED — the three roots differ in what stands beside: अञ्चतेः\n  सुबन्तमात्र उपपदे — प्राङ्, प्रत्यङ्; but युजेः क्रुञ्चेश्च\n  केवलादेव, from the BARE root — युङ्, क्रुङ् — since सोपपदात् तु\n  सत्सूद्विष० इत्यादिना क्विब् भवति, अश्वयुक्. One row wants a\n  companion and another wants none, which no rule before this had\n  needed.\n\nSETTLED — and the contrast now runs end to end. It stood as a\n  DEBT while 3.2.61 was uncodified: with a companion युज्\n  should take that rule's क्विप्, and the fall-through landed\n  on 3.2.1 instead. 3.2.61 was registered in the next block\n  and the test asserting the debt went red, which is what a\n  debt written as a test is for. युङ् bare by this rule,\n  अश्वयुक् by 3.2.61.\n\nSETTLED — नलोपः कस्माद् न भवति? निपातनसाहचर्यात्: the न of\n  क्रुञ्च् is not dropped, BY THE COMPANY the roots keep with the\n  fixed words in the same sūtra. An argument from a rule's own\n  composition — because the roots stand alongside निपातन,\n  something irregular is allowed them too.",
    "3.2.60": "SETTLED — त्यदादिषु दृशोऽनालोचने कञ् च: त्यादृशः and त्यादृक्,\n  तादृशः and तादृक्, यादृशः and यादृक् — चकारात् क्विन् च, so both\n  affixes stand. One row with `also`.\n\nSETTLED — अनालोचन इति किम्? तं पश्यति तद्दर्शः. And the vṛtti\n  says why the condition is needed: त्यादृगादयो हि\n  रूढिशब्दप्रकारा नैवात्र दर्शनक्रिया विद्यते — these are settled\n  words of their kind and there is no act of seeing in them at\n  all. 'Such as that' has stopped meaning 'looking like that'.\n\nSETTLED — कञो ञकारो विशेषणार्थः, for 4.1.15 ठक्ठञ्कञ् — the third\n  marker in this pāda written for a rule an adhyāya or more away,\n  after 3.2.38's च and 3.2.58's न.\n\nSCOPE — two vārttikas: समानान्ययोश्चेति वक्तव्यम् (सदृशः,\n  अन्यादृशः) is codified into the list, since it only adds\n  companions; दृशेः क्सश्च वक्तव्यः (तादृक्षः, कीदृक्षः) adds a\n  THIRD affix and is recorded, the row already carrying two.",
    "3.2.61": 'SETTLED — सत्सूद्विषद्रुहदुहयुजविदभिदच्छिदजिनीराजामुपसर्गेऽपि\n  क्विप्: शुचिषत्, अण्डसूः, मित्रद्विट्, मित्रध्रुक्, गोधुक्,\n  अश्वयुक्, वेदवित्, काष्ठभित्, रज्जुच्छिद्, शत्रुजित्, सेनानीः,\n  सम्राट् — and उपसर्गेऽपि, so प्रद्विट् stands beside मित्रद्विट्.\n\nSETTLED — कर्मग्रहणं तु स्पृशोऽनुदके क्विन् इत्यतः प्रभृति न\n  व्याप्रियते: the कर्म that ran through the early part of the\n  pāda has stopped by 3.2.58, and only सुपि comes down. A second\n  अनुवृत्ति ended by the commentary, after 3.2.48 and 3.2.68.\n\nSETTLED — उपसर्गग्रहणं ज्ञापनार्थम्, A ज्ञापक. Mentioning the\n  preverb here TELLS US something about elsewhere: अन्यत्र\n  सुब्ग्रहण उपसर्गग्रहणं न भवति — where सुप् is mentioned and the\n  preverb is not, as at 3.1.106 वदः सुपि क्यप् च, the preverb is\n  not meant. A rule saying something by the fact of its own\n  wording, which is a kind of evidence distinct from what it\n  states.\n\nSETTLED — THREE ROOT AMBIGUITIES SETTLED BY HAND. सू is सूतेः\n  आदादिकस्य and not सुवतेः तौदादिकस्य, and the ground is the\n  company it keeps: द्विषा साहचर्यात्. युज् is BOTH युजिर् योगे\n  and युज समाधौ, द्वयोरपि ग्रहणम्. विद् is three of the four —\n  ज्ञाने, सत्तायाम्, विचारणे — but न लाभार्थस्य विदेः, अकारस्य\n  विवक्षितत्वात्, the shape of the citation excluding the fourth.\n\nSETTLED — AND THE VṚTTI ENDS BY CALLING THE RULE REDUNDANT:\n  अन्येभ्योऽपि दृश्यते, क्विप् च इति सामान्येन वक्ष्यति,\n  तस्यैवायं प्रपञ्चः — 3.2.75 and 3.2.76 will say this generally,\n  and this rule is only their working-out. Recorded because it\n  bears on how 3.2.75 is codified: the general rule is real, and\n  what holds it back is usage rather than scope.',
    "3.2.62": 'SETTLED — भजो ण्विः: अर्धं भजते अर्धभाक्; उपसर्गेऽपि, प्रभाक्.',
    "3.2.63": 'SETTLED — छन्दसि सहः: तुराषाट्. सहेः साडः सः (8.3.56) gives the ष\n  and अन्येषामपि दृश्यते (6.3.137) the long vowel — both cited,\n  neither called: they act on the finished form.',
    "3.2.64": 'SETTLED — वहश्च: प्रष्ठवाट्, दित्यवाट्.\n  योगविभाग उत्तरार्थः — split from 3.2.63 for the rules after,\n  which want वह् and not सह्.',
    "3.2.65": 'SETTLED — कव्यपुरीषपुरीष्येषु ञ्युट्: कव्यवाहनः पितॄणाम्,\n  पुरीषवाहणः, पुरीष्यवाहनः — each with the Vedic passage the\n  vṛtti cites for it.',
    "3.2.66": "SETTLED — हव्येऽनन्तः पादम्: अग्निश्च हव्यवाहनः.\n\nSETTLED — THE CONDITION IS PROSODIC AND NOT GRAMMATICAL, and it\n  is the first of its kind in this project: the root must not\n  stand at the end of a पाद, a metrical quarter.\n  अनन्तः पादमिति किम्? हव्यवाडग्निरजरः पिता नः — at the quarter's\n  end the other form stands. So a rule of grammar turns on where\n  a word sits in a VERSE, which no condition the codification had\n  could express, and which needed a field of its own.",
    "3.2.67": 'SETTLED — जनसनखनक्रमगमो विट्: अब्जाः, गोजाः, गोषाः, नृषाः,\n  बिसखाः, दधिक्राः, अग्रेगा नेतॄणाम्.\n\nSETTLED — TWO OF THE FIVE ARE DOUBLED, as at 3.2.61 and 3.2.39:\n  जन जनने and जनी प्रादुर्भावे, षणु दाने and वन षण संभक्तौ,\n  द्वयोरपि ग्रहणम् in each case.\n\nSETTLED — ONE MARKER DOING TWO JOBS IN TWO LATER RULES: टकारः\n  सामान्यग्रहणाविघातार्थः for 6.1.67 वेरपृक्तस्य, and\n  विशेषणार्थः for 6.4.41 विड्वनोरनुनासिकस्यात्. Both cited, not\n  called.',
    "3.2.68": 'SETTLED — अदोऽनन्ने: आममत्ति आमात्, सस्यात्.\n  अनन्न इति किम्? अन्नादः.\n\nSETTLED — छन्दसीति निवृत्तम्: the Vedic condition that ran from\n  3.2.63 STOPS here, so this rule holds in ordinary speech too.\n  The third अनुवृत्ति in this pāda ended by the commentary rather\n  than by the text, after 3.2.48 and 3.2.61.',
    "3.2.69": "SETTLED — क्रव्ये च: क्रव्यमत्ति क्रव्यात्.\n\nSETTLED — पूर्वेणैव सिद्धे वचनम् असरूपबाधनार्थम्, तेन अण् न\n  भवति. 3.2.68 gives this already; the rule is stated to keep out\n  the असरूप अण् that 3.1.94 would otherwise let stand beside it.\n  The third rule of the project repeated to DEFEAT another, after\n  3.1.109's क्यप् and 3.2.44's अण्, so the row carries weight its\n  conditions do not warrant.\n\nSETTLED — AND THE VṚTTI THEN EXPLAINS THE FORM THAT DOES HAVE\n  अण्: कथं तर्हि क्रव्यादः? कृत्तविकृत्तशब्द उपपदेऽण्, तस्य च\n  पृषोदरादिपाठात् क्रव्यभावः — the companion is really\n  कृत्तविकृत्त and becomes क्रव्य by irregular formation. So the\n  two words differ in sense and not only in affix:\n  कृत्तविकृत्तपक्वमांसभक्षः क्रव्याद उच्यते, आममांसभक्षः क्रव्यात्\n  — one eats flesh cut up and cooked, the other eats it raw.",
    "3.2.70": "SETTLED — दुहः कब् घश्च: कामदुघा धेनुः, अर्घदुघा, घर्मदुघा.\n  घकारश्चान्तादेशः, the घ replacing the root's final.\n\nSETTLED — AND IT COMPETES WITH 3.2.61, WHICH NAMES दुह् AMONG ITS\n  TWELVE. Both reach दुह् with a सुबन्त and by stated conditions\n  they tie, so the resolver needed a tie-break on NARROWNESS: a\n  rule naming one root is more specific than one naming twelve.\n  Without it कामदुघा came out with 3.2.61's क्विप् — the affix\n  that gives गोधुक्.",
    "3.2.71": 'SETTLED — मन्त्रे श्वेतवहोक्थशस्पुरोडाशो ण्विन्: श्वेता एनं वहन्ति\n  श्वेतवा इन्द्रः; उक्थानि शंसति उक्थशा यजमानः; पुरो दाशन्त एनं\n  पुरोडाः.\n\nSETTLED — THE SŪTRA IS PART FIXING AND PART RULE, and the vṛtti\n  divides it exactly: धातूपपदसमुदाया निपात्यन्ते\n  अलाक्षणिककार्यसिद्ध्यर्थम्, प्रत्ययस्तु विधीयत एव — the whole\n  root-and-companion compounds are FIXED so that their irregular\n  operations come out, but the AFFIX is genuinely prescribed. So\n  the rows give the affix and the notes carry what is fixed in\n  each: नलोपः for उक्थशा, डत्वम् for पुरोडाः.\n\nSETTLED — the second word takes its companion either way: उक्थ\n  कर्मणि करणे वा, उक्थानि शंसति or उक्थैर्वा शंसति.\n\nSCOPE — श्वेतवहादीनां डस्पदस्येति वक्तव्यम्: श्वेतवोभ्याम्,\n  श्वेतवोभिः. पदस्येति किम्? श्वेतवाहौ, श्वेतवाहः.',
    "3.2.72": 'SETTLED — अवे यजः: त्वं यज्ञे वरुणस्यावया असि.\n  योगविभाग उत्तरार्थः, split from 3.2.71 for the rule after.',
    "3.2.73": 'SETTLED — विजुपे छन्दसि: उपयड्भिरूर्ध्वं वहन्ति, उपयट्त्वम्.\n  छन्दोग्रहणं ब्राह्मणार्थम् — the mention of छन्दस् is for the\n  Brāhmaṇa texts. विचः चित्करणं सामान्यग्रहणाविघातार्थम् for\n  6.1.67 वेरपृक्तस्य.\n\nSETTLED — THE RULE IS A नियम AND NOT A PROVISION, and the vṛtti\n  argues it out: किमर्थमिदमुच्यते, यावता अन्येभ्योऽपि दृश्यन्ते\n  इति यजेरपि विच् सिद्ध एव? — why state this at all, when 3.2.75\n  gives यज् its विच् already? यजेर्नियमार्थमेतत्: it exists to\n  RESTRICT — उपयजेश्छन्दस्येव, न भाषायाम्, in the Veda only and\n  not in speech. A rule whose whole work is to narrow another,\n  which is why it is codified with the Vedic condition and not\n  merely as a provision: the condition IS the rule.',
    "3.2.74": 'SETTLED — आतो मनिन्क्वनिब्वनिपश्च: सुदामा, अश्वत्थामा; क्वनिप्\n  सुधीवा, सुपीवा; वनिप् भूरिदावा, घृतपावा. And चकाराद् विज्\n  भवति — a FOURTH affix out of the च: कीलालपाः, शुभंयाः,\n  रामस्योपदाः. सुप्युपसर्गेऽपि, so a preverb does not stop it.',
    "3.2.75": "SETTLED — अन्येभ्योऽपि दृश्यन्ते: सुशर्मा; क्वनिप् प्रातरित्वा;\n  वनिप् विजावा, अग्रेगावा; विच् रेडसि. छन्दसीति निवृत्तम्, so it\n  is not held to the Veda, and अनाकारान्तेभ्यः, after roots that\n  do NOT end in आ — the complement of 3.2.74.\n\nSETTLED — THE RULE IS DELIBERATELY OPEN AT EVERY JOINT.\n  अपिशब्दः सर्वोपाधिव्यभिचारार्थः — the अपि is written so that\n  EVERY condition may be departed from; and निरुपपदादपि भवति, it\n  works with no companion at all, धीवा, पीवा.\n\nSETTLED — AND WHAT HOLDS IT BACK IS USAGE, NOT SCOPE:\n  दृशिग्रहणं प्रयोगानुसरणार्थम् — 'are SEEN' is written so that\n  one FOLLOWS USAGE. Read as a provision the rule would hand four\n  affixes to every root in the language; read as the vṛtti reads\n  it, it licenses what is attested. So it is codified with a\n  condition the caller must assert, and that condition is the\n  codification of दृश्यन्ते itself. The same ground as 3.2.1's\n  अनभिधानात्, taken from the other side: there usage withholds\n  what a rule would give, here usage is what a rule defers to.",
    "3.2.76": 'SETTLED — क्विप् च: सर्वधातुभ्यः सोपपदेभ्यो निरुपपदेभ्यश्च,\n  छन्दसि भाषायां च — उखायाः स्रंसते उखास्रत्, पर्णध्वत्,\n  वाहाभ्रट्. The widest rule of the pāda: every root, companion or\n  none, Veda or speech.\n\nSETTLED — AND IT IS WHY THE FOUR नियम RULES EXIST. After this\n  there is nothing left to provide, so 3.2.87, 3.2.89, 3.2.90 and\n  3.2.91 can only RESTRICT. Held to attested forms for the reason\n  3.2.75 is: read as a bare provision it would put क्विप् after\n  every root there is.',
    "3.2.77": "SETTLED — स्थः क च: शंस्थः, शंस्थाः.\n\nSETTLED — AND THE VṚTTI ASKS WHY IT IS SAID: किमर्थमिदमुच्यते,\n  यावता सुपि स्थः इति कः सिद्ध एव, अन्येभ्योऽपि दृश्यते इति\n  क्विप्? — 3.2.4 gives the क and 3.2.178 the क्विप् already.\n  बाधकबाधनार्थं पुनर्वचनम्: it is repeated to DEFEAT 3.2.14's अच्.\n  The fourth बाधकबाधन of the project, after 3.1.109, 3.2.44 and\n  3.2.69.\n\nSETTLED — the row is held to शम्, and that is not a narrowing of\n  the sūtra but a reading of where its weight belongs. Left\n  general it outranked 3.2.4 and took समस्थः from it — the same\n  affix, the wrong rule named. Everywhere but शम्, 3.2.4 already\n  answers; at शम् this rule has work to do.",
    "3.2.78": 'SETTLED — सुप्यजातौ णिनिस्ताच्छील्ये: उष्णभोजी, शीतभोजी.\n  अजाताविति किम्? ब्राह्मणानामन्त्रयिता. ताच्छील्य इति किम्?\n  उष्णं भुङ्क्ते कदाचित्.\n\nSETTLED — A WORD REPEATED IN ORDER TO END SOMETHING: सुपीति\n  वर्तमाने पुनः सुब्ग्रहणम् उपसर्गनिवृत्त्यर्थम् — सुप् is already\n  running, and saying it again is how the PREVERB is stopped. The\n  pāda has now shown three uses of repetition: to defeat another\n  rule (3.2.44, 3.2.77), to narrow (3.2.93), and here to end an\n  अनुवृत्ति.\n\nSCOPE — three vārttikas: उत्प्रतिभ्यामाङि सर्तेरुपसंख्यानम्\n  (उदासारिण्यः, प्रत्यासारिण्यः), साधुकारिणि च (साधुकारी,\n  साधुदायी), ब्रह्मणि वदः (ब्रह्मवादिनो वदन्ति).',
    "3.2.79": "SETTLED — कर्तर्युपमाने: उष्ट्र इव क्रोशति उष्ट्रक्रोशी,\n  ध्वाङ्क्षरावी. उपपदकर्ता प्रत्ययार्थस्य कर्तुरुपमानम् — the\n  companion is the agent of its OWN act and is what this rule's\n  agent is likened to. कर्तरीति किम्? अपूपानिव भक्षयति माषान् —\n  likened as object, and the affix does not come. उपमान इति किम्?\n  उष्ट्रः क्रोशति.\n\nSETTLED — अताच्छील्यार्थ आरम्भः, जात्यर्थो वा: written to reach\n  past 3.2.78's conditions. The fifth time in this pāda a rule\n  exists for what the rule before it left out.",
    "3.2.80": "SETTLED — व्रते: स्थण्डिलशायी, अश्राद्धभोजी. व्रत इति शास्त्रतो\n  नियम उच्यते, and कामचारप्राप्तौ नियमः — a restriction where\n  freedom would otherwise hold: सति शयने स्थण्डिल एव शेते नान्यत्र.\n  व्रत इति किम्? स्थण्डिले शेते देवदत्तः.\n\nSETTLED — समुदायोपाधिश्चायम्, धातूपपदप्रत्ययसमुदायेन व्रतं गम्यते:\n  the condition attaches to the WHOLE — root and companion and\n  affix together — and not to any part of it. The first समुदायोपाधि\n  the project has met; 3.2.92's अग्न्याख्या is the second.",
    "3.2.81": "SETTLED — बहुलमाभीक्ष्ण्ये: कषायपायिणो गान्धाराः, क्षीरपायिण\n  उशीनराः, सौवीरपायिणो बाह्लीकाः.\n\nSETTLED — AND IT IS EXPRESSLY NOT ताच्छील्य: आभीक्ष्ण्यं\n  पौनःपुन्यम्, तात्पर्यम् आसेवैव, ताच्छील्याद् अन्यत् — again and\n  again, an intentness, and something OTHER than 3.2.78's\n  disposition. The second time this project has had to keep two\n  neighbouring senses apart by the commentary's own insistence,\n  after 3.1.149's समभिहार against 3.1.22's.\n\nSETTLED — बहुलग्रहणात् the rule does not reach everywhere:\n  कुल्माषखाद इत्यत्र न भवति.",
    "3.2.82": "SETTLED — मनः: दर्शनीयमानी, शोभनमानी.\n\nSETTLED — THE ROOT IS PINNED BY A CONSEQUENCE ONE RULE LATER:\n  बहुलग्रहणानुवृत्तेर् मन्यतेर्ग्रहणम्, न मनुतेः — मन्यते of class\n  four and not मनुते of class eight, and the reason is\n  उत्तरसूत्रे हि खश्प्रत्यये विकरणकृतो विशेषः स्यात्: with\n  3.2.83's खश् the class-marker would show a difference. A root\n  disambiguated not by its sense or its company but by what a\n  later rule would do with it.",
    "3.2.83": 'SETTLED — आत्ममाने खश् च: आत्मनो मननम् आत्ममानः — दर्शनीयमात्मानं\n  मन्यते दर्शनीयंमन्यः, and चकाराद् णिनिश्च, दर्शनीयमानी.\n  पण्डितंमन्यः, पण्डितमानी.\n  आत्ममान इति किम्? दर्शनीयमानी देवदत्तस्य यज्ञदत्तः — thought of\n  another, and this rule does not reach it.',
    "3.2.84": "SETTLED — भूते, AND IT IS AN अधिकार AND NOT A PROVISION. It adds\n  no affix. यदित ऊर्ध्वम् अनुक्रमिष्यामो भूत इत्येवं तद्\n  वेदितव्यम् — whatever is said from here on is to be understood\n  as of the past, and it runs to 3.2.122, stopping where\n  3.2.123 वर्तमाने लट् takes over.\n\nSETTLED — धात्वधिकाराच्च धात्वर्थे भूत इति विज्ञायते: it is the\n  ROOT's meaning that is past, not the word's, because the root\n  section is what is running.\n\nSETTLED — codified as its own entry point, as the four headings\n  of 3.1 were, and every row from 3.2.85 on carries the condition\n  the heading confers. भूत इति किम्? अग्निष्टोमेन यजते.",
    "3.2.85": "SETTLED — करणे यजः: अग्निष्टोमेनेष्टवान् अग्निष्टोमयाजी.\n  अग्निष्टोमः फलभावनायां करणं भवति.\n  णिनिरनुवर्तते, न खश् — only one of 3.2.83's two affixes comes\n  down, which the commentary has to say because the rule does not.",
    "3.2.86": "SETTLED — कर्मणि हनः: पितृव्यघाती, मातुलघाती.\n\nSETTLED — a vārttika made a condition rather than merely\n  recorded: कुत्सितग्रहणं कर्तव्यम्, the killing must be\n  blameworthy — इह मा भूत् चौरं हतवान्. Codified because the\n  counter-example turns on it, as 3.2.24's व्रीहिवत्स was.",
    "3.2.87": "SETTLED — ब्रह्मभ्रूणवृत्रेषु क्विप्: ब्रह्महा, भ्रूणहा, वृत्रहा.\n\nSETTLED — AND IT PROVIDES NOTHING WHATEVER.\n  किमर्थमिदमुच्यते, यावता सर्वधातुभ्यः क्विब् विहित एव? — 3.2.76\n  has already given क्विप् to every root. ब्रह्मादिषु हन्तेः\n  क्विब्वचनं नियमार्थम्, and the vṛtti counts the restriction\n  FOURFOLD: only after these companions and no other; only from\n  हन् and no other root; only क्विप् and no other affix; and only\n  in the past.\n\nSETTLED — तदेतद् वक्ष्यमाणबहुलग्रहणस्य पुरस्तादपकर्षणाद् लभ्यते:\n  that fourfold reading is got by dragging 3.2.88's बहुल BACKWARD\n  over this rule. A word from a later sūtra pulled earlier to make\n  the earlier one readable.",
    "3.2.88": 'SETTLED — बहुलं छन्दसि: मातृहा सप्तमं नरकं प्रविशेत्, पितृहा —\n  with companions 3.2.87 does not name.\n  पूर्वेण नियमाद् अप्राप्तः क्विप् प्रत्ययो विधीयते: what the\n  नियम before shut out is given back here, for the Veda. And\n  बहुलम् is why the other form still stands: न च भवति मातृघातः.',
    "3.2.89": 'SETTLED — सुकर्मपापमन्त्रपुण्येषु कृञः: सुकृत्, कर्मकृत्, पापकृत्,\n  मन्त्रकृत्, पुण्यकृत्.\n  कर्मणीति वर्तते, तदसंभवात् सुशब्दं वर्जयित्वा परिशिष्टानां\n  विशेषणं भवति — सु cannot be an object, so the कर्म qualifies the\n  other four only.\n\nSETTLED — अयमपि नियमार्थ आरम्भः, AND HERE THE RESTRICTION IS\n  THREEFOLD AND NOT FOURFOLD: धातुनियमं वर्जयित्वा\n  कालोपपदप्रत्ययनियमः — the ROOT is not restricted. So other\n  companions do work: शास्त्रकृत्, भाष्यकृत्. The vṛtti counting\n  the kinds of restriction rule by rule is what makes the\n  difference from 3.2.87 visible at all.',
    "3.2.90": 'SETTLED — सोमे सुञः: सोमसुत्, सोमसुतौ, सोमसुतः.\n  अयमपि नियमार्थ आरम्भः, चतुर्विधश्चात्र नियम इष्यते,\n  धातुकालोपपदप्रत्ययविषयः — fourfold again, the root restricted\n  here where 3.2.89 left it free.',
    "3.2.91": "SETTLED — अग्नौ चेः: अग्निचित्, अग्निचितौ, अग्निचितः.\n  अत्रापि पूर्ववच्चतुर्विधो नियम इष्यते — fourfold, as at 3.2.90.\n  The vṛtti says only 'as before' and does not count them again,\n  which is worth noting: the counting at 3.2.87 and 3.2.89 is\n  what makes the difference between those two visible, and here\n  the reader is expected to carry it over.",
    "3.2.92": "SETTLED — कर्मण्यग्न्याख्यायाम्: श्येन इव चीयते श्येनचित्,\n  कङ्कचित्.\n\nSETTLED — धातूपपदप्रत्ययसमुदायेन चेद् अग्न्याख्या गम्यते: the\n  WHOLE must name a fire, and the condition is on the समुदाय as\n  3.2.80's was — the second of that shape in this pāda.\n  आख्याग्रहणं रूढिसंप्रत्ययार्थम्: आख्या is said so that a SETTLED\n  name is meant, अग्न्यर्थो हीष्टकाचय उच्यते श्येनचिदिति — a\n  hawk-shaped altar of bricks, not a hawk.",
    "3.2.93": 'SETTLED — कर्मणीनिविक्रयः: सोमविक्रयी, रसविक्रयी.\n\nSETTLED — कर्मन् IS SAID AGAIN THOUGH IT IS ALREADY RUNNING, and\n  the repetition NARROWS: कर्मणीति वर्तमाने पुनः कर्मग्रहणं कर्तुः\n  कुत्सानिमित्ते कर्मणि यथा स्यात्, कर्ममात्रे मा भूत् — the object\n  must be one that makes the AGENT blameworthy, not any object\n  whatever. इह न भवति धान्यविक्रायः: selling grain is no reproach,\n  selling soma is. The third use of repetition in this pāda —\n  3.2.44 and 3.2.77 repeat to defeat, 3.2.78 to end an अनुवृत्ति,\n  and this one to narrow.',
    "3.2.94": "SETTLED — दृशेः क्वनिप्: मेरुदृश्वा, परलोकदृश्वा.\n\nSETTLED — A FIFTH USE OF REPETITION, and one this pāda had not\n  shown before: अन्येभ्योऽपि दृश्यन्ते इति क्वनिपि सिद्धे\n  पुनर्वचनं प्रत्ययान्तरनिवृत्त्यर्थम्. 3.2.75 gives क्वनिप्\n  already — this is said to SHUT OUT the other three affixes that\n  rule would give beside it. Not to defeat a rule (3.2.44,\n  3.2.77), not to end an अनुवृत्ति (3.2.78), not to narrow a\n  condition (3.2.93), but to keep the rest of one rule's own list\n  away.",
    "3.2.95": 'SETTLED — राजनि युधिकृञः: राजयुध्वा, राजकृत्वा.\n\nSETTLED — AND THE VṚTTI MEETS AN OBJECTION ABOUT THE ROOT ITSELF:\n  ननु च युधिरकर्मकः? — युध् takes no object, so how can कर्मणि\n  hold of it? अन्तर्भावितण्यर्थः सकर्मको भवति: it absorbs a\n  causative sense and so becomes transitive, राजानं योधितवान्\n  इत्यर्थः. A root made to satisfy a condition by being read as\n  containing an affix that is not written.',
    "3.2.96": "SETTLED — सहे च: सहयुध्वा, सहकृत्वा.\n\nSETTLED — and the companion is NOT the object here, on a ground\n  about what the word denotes: असत्त्ववाचित्वाद् नोपपदं कर्मणा\n  विशेष्यते — सह names no substance, so कर्मन् cannot qualify it.\n  The same shape of argument as 3.2.13's, where what the roots\n  could do settled which condition was meant.",
    "3.2.97": 'SETTLED — सप्तम्यां जनेर्डः: उपसरे जातः उपसरजः, मन्दुरजः. The\n  companion stands in the locative, so the role is the place.',
    "3.2.98": "SETTLED — पञ्चम्यामजातौ: बुद्धिजः, संस्कारजः, दुःखजः.\n  अजाताविति किम्? हस्तिनो जातः, अश्वाज् जातः — of a class the\n  affix does not come, the same condition as 3.2.78's.",
    "3.2.99": "SETTLED — उपसर्गे च संज्ञायाम्, and समुदायोपाधिः संज्ञा: the NAME\n  is conveyed by the whole and not by any part of it. The third\n  समुदायोपाधि of this pāda, after 3.2.80's व्रत and 3.2.92's\n  अग्न्याख्या — by now plainly a device of the text rather than a\n  remark about one rule.",
    "3.2.100": 'SETTLED — अनौ कर्मणि: पुमांसम् अनुजातः पुमनुजः, स्त्र्यनुजः.',
    "3.2.101": 'SETTLED — अन्येष्वपि दृश्यते, AND THE VṚTTI WALKS THROUGH EVERY\n  ONE OF THE FOUR RULES BEFORE IT, showing each condition\n  departed from in turn: सप्तम्याम् इत्युक्तम्, असप्तम्याम् अपि\n  दृश्यते — अजः; पञ्चम्यामजातौ इत्युक्तम्, जातावपि दृश्यते —\n  ब्राह्मणजो धर्मः, क्षत्रियजं युद्धम्; उपसर्गे च संज्ञायाम्\n  इत्युक्तम्, असंज्ञायामपि दृश्यते — अभिजाः, परिजाः केशाः;\n  अनौ कर्मणि इत्युक्तम्, अकर्मण्यपि दृश्यते — अनुजः.\n  A rule that is the systematic undoing of the four before it.\n\nSETTLED — अपिशब्दः सर्वोपाधिव्यभिचारार्थः, and तेन धात्वन्तराद्\n  अपि भवति, कारकान्तरेऽपि: even from ANOTHER ROOT — परितः खाता\n  परिखा, आखा. The third open rule of the pāda, after 3.2.75 and\n  3.2.76, and held to attested forms for the same reason: read as\n  a provision it would reach everything.',
    "3.2.102": "SETTLED — निष्ठा, AND IT IS A संज्ञा RULE: it says that the affix\n  bearing that name comes where the act is past, and adds nothing\n  of its own. कृतम्, कृतवान्, भुक्तम्, भुक्तवान्.\n\nSETTLED — WHICH affixes bear the name is 1.1.26 क्तक्तवतू निष्ठा's\n  business, and that rule is codified, so it is ASKED. The reuse\n  is declared. A refusal shows the split working: an affix that is\n  no निष्ठा is refused WITHOUT naming this rule, since 1.1.26 is\n  what withheld the name; a निष्ठा outside the past is refused BY\n  this rule, since refusing is then the whole of what it does.\n\nSETTLED — AND THE VṚTTI RAISES A CIRCULARITY AGAINST ITSELF:\n  निष्ठायाम् इतरेतराश्रयत्वाद् अप्रसिद्धिः — the name is conferred\n  on affixes that do not yet exist, and the affixes are\n  introduced by the name, so neither can begin. नैष दोषः, भाविनी\n  संज्ञा विज्ञायते: the name is understood as FORTHCOMING, applying\n  to what will bear it once produced. सामर्थ्यात् क्तक्तवत्वोर्\n  विधानम् एतत् — and the force of saying it is that this rule\n  introduces the two.\n\nSCOPE — आदिकर्मणि निष्ठा वक्तव्या: a vārttika giving it for the\n  BEGINNING of an act as well — प्रकृतः कटं देवदत्तः, Devadatta\n  has begun the mat.\n\nSETTLED — AND THIS PĀDA EXCEPTS IT TWICE, at its very end.\n  3.2.187 ञीतः क्तः and 3.2.188 मतिबुद्धिपूजार्थेभ्यश्च give क्त\n  in the PRESENT, and 3.2.187's vṛtti names this rule as the\n  reason they are needed: भूते निष्ठा विहिता वर्तमाने न\n  प्राप्नोतीति विधीयते. So the two answer from beside this one\n  rather than from the affix table — a reader asking when क्त\n  comes should find all three together.",
    "3.2.103": 'SETTLED — सुयजोर्ङ्वनिप्: सुत्वा, यज्वा. No companion is wanted —\n  the rule names two roots and nothing else, which after ninety\n  rules of उपपद conditions is worth marking.',
    "3.2.104": 'SETTLED — जीर्यतेरतृन्: जरन्, जरन्तौ, जरन्तः.\n  वासरूपेण निष्ठा — and by 3.1.94 the निष्ठा stands beside it,\n  जीर्णः, जीर्णवान्. So the rule does not shut the other out, and\n  the row carries both.',
    "3.2.105": "SETTLED — छन्दसि लिट्, where the past is meant, in the Veda.\n\nSETTLED — AND THE VṚTTI ASKS WHY, SINCE ANOTHER RULE GIVES IT\n  ALREADY: ननु च छन्दसि लुङ्लङ्लिटः इति सामान्येन लिड् विहित एव?\n  — 3.4.6 gives लिट् in the Veda. धातुसंबन्धे स विधिः, अयं\n  त्वविशेषेण: that rule is about the root's CONNECTION, this one\n  is unqualified. Two rules giving the same thing on different\n  grounds, and the commentary separating them by what each is\n  ABOUT rather than by what each produces.\n\nSETTLED — codified from its own entry point with 3.2.106–108,\n  because these do not add an affix to a root as the rest of the\n  pāda does: they put लिट् where the past is meant and then\n  substitute for it.",
    "3.2.106": 'SETTLED — लिटः कानज् वा, optionally: अग्निं चिक्यानः, सोमं\n  सुषुवाणः. न च भवति — अहं सूर्यमुभयतो ददर्श, where the ordinary\n  form stands.\n\nSETTLED — लिड्ग्रहणं किम्? The vṛtti asks why लिट् is named again\n  when it is running: न पूर्वस्यैव प्रकृतस्यादेशविधाने\n  विभक्तिविपरिणामो भविष्यति? — the case-ending could simply have\n  been read differently. लिण्मात्रस्य यथा स्यात्: naming it makes\n  the substitution reach EVERY लिट्, योऽपि परोक्षे विहितः, including\n  the one 3.2.115 gives. A sixth use of repetition —\n  to WIDEN what a rule reaches.',
    "3.2.107": 'SETTLED — क्वसुश्च: जक्षिवान्, पपिवान्. न च भवति — अहं सूर्यम्\n  उभयतो ददर्श.\n  योगविभाग उत्तरार्थः — split from 3.2.106 for the rule after,\n  which wants क्वसु and not कानच्.',
    "3.2.108": 'SETTLED — भाषायां सदवसश्रुवः: क्वसु for लिट् in ORDINARY SPEECH\n  too, after three roots and optionally — उपसेदिवान् कौत्सः\n  पाणिनिम्, अनूषिवान्, उपशुश्रुवान्.\n\nSETTLED — आदेशविधानाद् एव लिडपि तद्विषयोऽनुमीयते: prescribing a\n  SUBSTITUTE is how we know लिट् itself is available here — the\n  rule tells us about the thing it replaces. And तेन मुक्ते\n  यथाप्राप्तं प्रत्यया भवन्ति: where the option is not taken, the\n  ordinary forms stand — उपासदत्, उपासीदत्, उपससाद. So the entry\n  point reports the alternatives rather than one form.',
    "3.2.109": 'SETTLED — उपेयिवाननाश्वाननूचानश्च, and all three are निपातन:\n  उपेयिवान्, अनाश्वान्, अनूचानः.\n\nSETTLED — AND THE THREE DO NOT FIX THE SAME AFFIX. उपेयिवान् and\n  अनाश्वान् fix क्वसु; अनूचानः fixes कानच् — वचेर् अनुपूर्वात्\n  कर्तरि कानज् निपात्यते. One sūtra supplying two different\n  affixes among its three words, which is why each entry in the\n  lookup carries its own.\n\nSETTLED — the vṛtti works out a chain for the first: द्विर्वचनम्\n  अभ्यासदीर्घत्वम्, तत्सामर्थ्याद् एकादेशप्रतिबन्धः, and 7.2.67\n  वस्वेकाजाद्घसाम् would have refused the augment for being more\n  than one vowel — स निपात्यते. न चात्रोपसर्गस्तन्त्रम्: the\n  preverb is not essential, समीयिवान् and ईयिवान् stand too.',
    "3.2.110": 'SETTLED — लुङ्, भूतेऽर्थे वर्तमानाद् धातोः: अकार्षीत्, अहार्षीत्.\n  The widest rule of this run, and everything after it narrows.\n\nSETTLED — codified from its own entry point, the SIXTH kind this\n  pāda has needed. These rules do not add a कृत् affix at all:\n  they say which tense-ENDING is used, and their conditions are\n  about time and about the situation of speaking. A table of\n  उपपद affixes could not hold them without pretending they were\n  the same kind of thing.\n\nSCOPE — वसतेर्लुङ् रात्रिशेषे जागरणसंततौ वक्तव्यः: a vārttika for\n  वस् of a night passed awake — क्व भवान् उषितः? अहम् अत्र\n  अवात्सम्. Recorded.',
    "3.2.111": "SETTLED — अनद्यतने लङ्: अकरोत्, अहरत्.\n\nSETTLED — AND THE COMPOUND'S OWN FORM DOES THE EXCLUDING.\n  अनद्यतन is a बहुव्रीहिनिर्देश — अविद्यमानाद्यतने, 'having no\n  today in it'. बहुव्रीहिनिर्देशः किमर्थः? अद्य ह्यो वा\n  अभुक्ष्महि इति व्यामिश्रे मा भूत्: so that a MIXED case, 'we ate\n  today or yesterday', is not reached. Had the word been a\n  तत्पुरुष the mixed case would have slipped in. A condition\n  carried by which kind of compound the term is.\n\nSCOPE — परोक्षे च लोकविज्ञाते प्रयोक्तुर्दर्शनविषये लङ्:\n  अरुणद् यवनः साकेतम् — of an event widely known but not seen by\n  the speaker. Recorded.",
    "3.2.112": "SETTLED — अभिज्ञावचने लृट्: अभिजानासि देवदत्त कश्मीरेषु\n  वत्स्यामः? लङोऽपवादः. अभिज्ञा स्मृतिः.\n\nSETTLED — AND IT GIVES THE FUTURE ENDING FOR A PAST ACT. Every\n  rule here stands under 3.2.84 भूते, so the act is past — yet\n  लृट् is what comes. What is remembered was FUTURE to the\n  remembering, and the ending looks forward from inside the\n  memory rather than back from the speaking. Nothing in the code\n  needed changing for it; what it changes is any assumption that\n  an ending's name tells you the time.\n\nSETTLED — वचनग्रहणं पर्यायार्थम्: the word वचन is written so that\n  any SYNONYM of remembering counts and not अभिज्ञा alone —\n  अभिजानासि, स्मरसि, बुध्यसे, चेतयसे. Codified as a list of four\n  for that reason.",
    "3.2.113": "SETTLED — न यदि: अभिजानासि देवदत्त यत् कश्मीरेष्ववसाम.\n  पूर्वेण प्राप्तः प्रतिषिध्यते — what 3.2.112 gave is refused\n  where यद् stands with it. The one प्रतिषेध of this run.\n\nSETTLED — AND IT DOES NOT GOVERN WHAT IT EXCEPTS. What these\n  words then take is 3.2.111's लङ् — अवसाम, not *वत्स्यामः — so\n  that is the rule reported and this one rides on `blocked_by`.\n  The decision 2.3.72 settled and 3.2.23 followed.\n\nSETTLED — THE VṚTTI MARKS OFF ITS GROUND FROM THE NEXT RULE'S:\n  वासमात्रं स्मर्यते, न त्वपरं किंचिल् लक्ष्यते, तेन उत्तरसूत्रस्य\n  नायं विषयः — here only the dwelling is remembered and nothing\n  further is looked to. So the refusal holds only where the\n  speaker expects nothing more, and साकाङ्क्ष had to be made\n  tri-state: this rule requires its ABSENCE where 3.2.114\n  requires it. Without that the option of 3.2.114 was swallowed.",
    "3.2.114": 'SETTLED — विभाषा साकाङ्क्षे, and यदीति नानुवर्तते, उभयत्र\n  विभाषेयम्: यद् does NOT come down from 3.2.113, so the option\n  holds both with it and without — अभिजानासि देवदत्त कश्मीरेषु\n  वत्स्यामः, तत्रौदनं भोक्ष्यामहे, and equally with यद्.\n  A fifth अनुवृत्ति ended by the commentary rather than the text.\n\nSETTLED — WHAT साकाङ्क्ष MEANS, and the vṛtti defines it by the\n  relation between two clauses: लक्ष्यलक्षणयोः संबन्धे\n  प्रयोक्तुर् आकाङ्क्षा भवति — वासो लक्षणम्, भोजनं तु लक्ष्यम्.\n  The dwelling MARKS the time; the eating is what is being placed\n  by it. So the first clause is expectant only because a second\n  follows, and the condition is about the sentence and not the\n  word.',
    "3.2.115": "SETTLED — परोक्षे लिट्: चकार, जहार.\n\nSETTLED — AND THE VṚTTI RAISES A DIFFICULTY ABOUT THE WHOLE\n  NOTION. ननु च धात्वर्थः सर्वः परोक्ष एव? — is not every verbal\n  meaning out of sight, since what one sees are things and never\n  acts? सत्यम् एतत्, अस्ति तु लोके धात्वर्थेनापि कारकेषु\n  प्रत्यक्षाभिमानः, स यत्र नास्ति तत् परोक्षम् इत्युच्यते: true,\n  but people do take themselves to see an act in its\n  participants, and परोक्ष is where they do not. A grammatical\n  term defined by what speakers BELIEVE rather than by what is\n  so — which is a kind of definition this project had not met.\n\nSETTLED — and it can hold even of oneself: उत्तमविषयेऽपि\n  चित्तव्याक्षेपात् परोक्षता संभवत्येव — सुप्तोऽहं किल विललाप,\n  'asleep, I am told, I wailed'.\n\nSCOPE — अत्यन्तापह्नवे च लिड् वक्तव्यः: a vārttika for flat\n  denial — नाहं कलिङ्गान् जगाम. Recorded.",
    "3.2.116": 'SETTLED — हशश्वतोर्लङ् च: इति ह अकरोत् and इति ह चकार, शश्वद्\n  अकरोत् and शश्वच् चकार. चकाराल् लिट् च, so BOTH endings stand\n  where 3.2.115 would have given only the one. Codified as a row\n  carrying `also`, as 3.2.44 and 3.2.74 are.',
    "3.2.117": 'SETTLED — प्रश्ने चासन्नकाले: अगच्छद् देवदत्तः? जगाम देवदत्तः?\n  Both endings again, in a QUESTION about lately.\n  प्रश्न इति किम्? जगाम देवदत्तः — a statement, and only the one.\n  आसन्नकाल इति किम्? भवन्तं पृच्छामि, जघान कंसं किल वासुदेवः? —\n  asking about the far past, and the rule does not reach it.\n\nSETTLED — the condition is about the ACT OF ASKING and not about\n  any word in the sentence, which is why it is codified as its\n  own input rather than as a companion.',
    "3.2.118": 'SETTLED — लट् स्मे: नडेन स्म पुराधीयते, ऊर्णया स्म पुराधीयते.\n  लिटोऽपवादः — and it is the PRESENT ending for a past act, which\n  the particle स्म alone licenses.',
    "3.2.119": 'SETTLED — अपरोक्षे च: एवं स्म पिता ब्रवीति, इति स्मोपाध्यायः\n  कथयति. The same ending and the same companion where the act was\n  NOT out of sight.\n\nSETTLED — and this is why परोक्ष had to be tri-state rather than\n  a flag: 3.2.115 requires it, this rule requires its absence,\n  and the rest of the run says nothing either way. A condition\n  with three states because two rules take opposite sides of it.',
    "3.2.120": 'SETTLED — ननौ पृष्टप्रतिवचने: अकार्षीः कटं देवदत्त? ननु करोमि\n  भोः. लुङोऽपवादः. पृष्टप्रतिवचन इति किम्? नन्वकार्षीन् माणवकः.\n\nSETTLED — TWO CONDITIONS STOP RUNNING HERE: अनद्यतने परोक्षे इति\n  निवृत्तम्, भूतसामान्ये विधिरयम् — the rule is for the past at\n  large. The sixth अनुवृत्ति in this pāda ended by the commentary\n  rather than by the text, after 3.2.48, 3.2.61, 3.2.68, 3.2.78\n  and 3.2.114.',
    "3.2.121": 'SETTLED — नन्वोर्विभाषा: अकार्षीः कटं देवदत्त? न करोमि भोः, or\n  नाकार्षम्; अहं नु करोमि, or अहं न्वकार्षम्. The option is real,\n  so the present and the past ending both stand.',
    "3.2.122": "SETTLED — पुरि लुङ् चास्मे: वसन्तीह पुरा छात्राः, अवात्सुरिह पुरा\n  छात्राः. अस्म इति किम्? नडेन स्म पुराधीयते — with स्म it is\n  3.2.118's, so this rule names a companion in order to REFUSE\n  it, as 3.2.58 did.\n\nSETTLED — AND THE CONDITION ARRIVES BY A FROG'S LEAP.\n  अनद्यतनग्रहणम् इह मण्डूकप्लुत्या अनुवर्तते: अनद्यतन comes down\n  from 3.2.111 by LEAPING OVER the rules between, which had let\n  it go. A running condition that skips rather than flows — the\n  first मण्डूकप्लुति this project has met, and a reminder that\n  अनुवृत्ति is not simply positional. The codification cannot\n  represent running conditions at all, so every row states its\n  own; what a leap changes is only which rows should state this\n  one, and the note is the record that the question was asked.\n\nSETTLED — ताभ्यां मुक्ते पक्षे यथाविषयम् अन्येऽपि प्रत्यया\n  भवन्ति: where neither option is taken, still OTHER endings come\n  — अवसन्, ऊषुः. So the rule offers two and forbids nothing.",
    "3.2.123": "SETTLED — वर्तमाने लट्: पचति, पठति.\n\nSETTLED — प्रारब्धोऽपरिसमाप्तश्च वर्तमानः: the present is what is\n  BEGUN AND NOT FINISHED. Defined by the act's own course and not\n  by the moment of speaking, so it covers what is under way and\n  not merely what is happening now.\n\nSETTLED — and this is where 3.2.84's भूते heading STOPS. That\n  heading was said to run as far as this rule, and here it ends\n  because another time is named. The block boundary is the text's\n  own, not one chosen for convenience.",
    "3.2.124": "SETTLED — लटः शतृशानचावप्रथमासमानाधिकरणे: पचन्तं देवदत्तं पश्य,\n  पचमानं देवदत्तं पश्य; पचता कृतम्, पचमानेन कृतम्.\n  अप्रथमासमानाधिकरण इति किम्? देवदत्तः पचति.\n\nSETTLED — these SUBSTITUTE for लट् rather than being added to a\n  root, so they answer from their own entry point, as 3.2.105–108\n  do for लिट्.\n\nSETTLED — A SEVENTH USE OF REPETITION: लड्ग्रहणम्\n  अधिकविधानार्थम्. लट् is named again though it was running, and\n  what that buys is that the substitution reaches BEYOND the\n  stated condition — क्वचित् प्रथमासमानाधिकरणेऽपि भवति: सन्\n  ब्राह्मणः, विद्यमानो ब्राह्मणः, जुह्वत्, अधीयानः. The same job\n  3.2.106's लिड्ग्रहण did, so widening is now attested twice.\n\nSCOPE — माङि आक्रोशे gives मा पचन्, मा पचमानः. And केचिद्\n  विभाषाग्रहणम् अनुवर्तयन्ति, सा च व्यवस्थिता, तत्र यथादर्शनं\n  प्रयोगा नेतव्याः: some carry 3.2.121's विभाषा down here, read as\n  settled case by case. A reading the vṛtti reports without\n  adopting, so it is recorded and not codified.",
    "3.2.125": 'SETTLED — संबोधने च: हे पचन्, हे पचमान.\n  प्रथमासमानाधिकरणार्थ आरम्भः — the rule exists BECAUSE a\n  vocative agrees with a first-case word, which 3.2.124 shut out.\n  The seventh time in this pāda a rule is written to reach past\n  the condition of the rule before it, and by now the shape is a\n  habit of composition rather than a series of coincidences.',
    "3.2.126": "SETTLED — लक्षणहेत्वोः क्रियायाः. लक्षणे: शयाना भुञ्जते यवनाः,\n  तिष्ठन्तोऽनुशासति गणकाः. हेतौ: अर्जयन् वसति, अधीयानो वसति.\n  लक्ष्यते चिह्न्यते येन तल्लक्षणम्; जनको हेतुः.\n\nSETTLED — क्रियाया इति किम्? द्रव्यगुणयोर्मा भूत्: the mark must\n  be an ACT and not a thing or a quality — यः कम्पते सोऽश्वत्थः,\n  यदुत्प्लवते तल्लघु, यन्निषीदति तद् गुरु.\n\nSETTLED — AND THE COMPOUND'S OWN ORDER IS EVIDENCE:\n  लक्षणहेत्वोरिति निर्देशः पूर्वनिपातव्यभिचारलिङ्गम् — हेतु should\n  have stood first by the rules governing which member of a\n  compound comes first, and its not doing so is the SIGN that\n  those rules are departed from. The second time in this pāda a\n  compound's form carries an argument, after 3.2.111's बहुव्रीहि.",
    "3.2.127": "SETTLED — तौ सत्, AND IT IS A संज्ञा RULE: it names the two and\n  adds nothing. The second in this pāda, after 3.2.102 निष्ठा, so\n  naming is now a settled kind rather than a one-off.\n\nSETTLED — तौग्रहणम् उपाध्यसंसर्गार्थम्, शतृशानज्मात्रस्य संज्ञा\n  भवति: तौ is said so that the name attaches to शतृ and शानच् AT\n  LARGE and not only to them under the conditions of the rules\n  just given. So a शतृ got from anywhere is सत् — ब्राह्मणस्य\n  कुर्वन्, ब्राह्मणस्य करिष्यन्. A word written to STOP a\n  condition attaching, which is the mirror of 3.2.78's सुब्ग्रहण\n  stopping a preverb.\n\nSETTLED — सत्प्रदेशाः, where the name is used: 2.2.11 and the\n  rest. Cited, not called — those rules consume the name, and\n  this one confers it.",
    "3.2.128": 'SETTLED — पूङ्यजोः शानन्: पवमानः, यजमानः.\n\nSETTLED — A PRATYĀHĀRA FORMED ACROSS SŪTRAS, which this project\n  had not met. The vṛtti asks how the षष्ठीप्रतिषेध of 2.3.69 can\n  apply if these affixes are not लादेश at all — सोमं पवमानः,\n  नडमाघ्नानः — and answers तृन्निति प्रत्याहारनिर्देशात्: there is\n  a pratyāhāra तृन् whose members are RULES. क्व संनिविष्टानां\n  प्रत्याहारः? लटः शतृ० इत्यतः प्रभृति आ तृनो नकारात् — from\n  3.2.124 as far as the न of तृन् at 3.2.135. So the device that\n  abbreviates a span of SOUNDS is used here to abbreviate a span\n  of the grammar itself.\n\nSCOPE — द्विषः शतुर्वावचनम्, a vārttika: चौरस्य द्विषन् beside\n  चौरं द्विषन्. Recorded.',
    "3.2.129": "SETTLED — ताच्छील्यवयोवचनशक्तिषु चानश्, and the vṛtti glosses all\n  three: ताच्छील्यं तत्स्वभावता, वयः शरीरावस्था यौवनादिः, शक्तिः\n  सामर्थ्यम्. ताच्छील्ये कतीह मण्डयमानाः; वयोवचने कतीह कवचं\n  पर्यस्यमानाः; शक्तौ कतीह पचमानाः.\n\nSETTLED — ताच्छील्य here is the same notion 3.2.78 and 3.2.11\n  used, and the gloss is word for word the same, तत्स्वभावता. So\n  the field is shared rather than split — the opposite call from\n  3.1.149's समभिहार, which had to be kept apart from 3.1.22's\n  because the vṛtti glossed the two differently.",
    "3.2.130": 'SETTLED — इङ्धार्योः शत्रकृच्छ्रिणि: अधीयन् पारायणम्,\n  धारयन्नुपनिषदम्. अकृच्छ्रः सुखसाध्यो यस्य कर्तुर्धात्वर्थः\n  सोऽकृच्छ्री — one for whom the act comes easily.\n  अकृच्छ्रिणीति किम्? कृच्छ्रेणाधीते, कृच्छ्रेण धारयति.',
    "3.2.131": "SETTLED — द्विषोऽमित्रे: द्विषन्, द्विषन्तौ, द्विषन्तः.\n  अमित्रः शत्रुः. अमित्र इति किम्? द्वेष्टि भार्या पतिम् — of a\n  wife hating a husband the rule does not reach, the hatred not\n  being an enemy's.",
    "3.2.132": 'SETTLED — सुञो यज्ञसंयोगे: सर्वे सुन्वन्तः, सर्वे यजमानाः\n  सत्रिण उच्यन्ते.\n\nSETTLED — संयोगग्रहणं प्रधानकर्तृप्रतिपत्त्यर्थम्, याजकेषु मा\n  भूत्: the word संयोग is there so that the PRINCIPAL doer is\n  meant — the sacrificer — and not the officiating priests. A\n  word chosen to pick out which participant is intended.\n  यज्ञसंयोग इति किम्? सुनोति सुराम्.',
    "3.2.133": 'SETTLED — अर्हः प्रशंसायाम्: अर्हन्निह भवान् विद्याम्, अर्हन्निह\n  भवान् पूजाम्. प्रशंसा स्तुतिः.\n  प्रशंसायामिति किम्? अर्हति चौरो वधम् — deserving in the bad\n  sense, and the rule does not reach it. The same root 3.2.12\n  gave अच् to, now under a condition about praise.',
    "3.2.134": "SETTLED — आ क्वेस्तच्छीलतद्धर्मतत्साधुकारिषु, AND IT IS A HEADING:\n  it adds no affix and puts every rule as far as 3.2.177 under\n  three senses at once. यानित ऊर्ध्वम् अनुक्रमिष्यामः\n  तच्छीलादिषु कर्तृषु ते वेदितव्याः.\n\nSETTLED — AND THE VṚTTI SEPARATES THE THREE, which is worth the\n  space because the first two look alike and are not:\n  तच्छीलो यः स्वभावतः फलनिरपेक्षस्तत्र प्रवर्तते — one who does\n    the thing by NATURE, with no eye to what comes of it;\n  तद्धर्मा तदाचारः, यः स्वधर्मे ममायमिति प्रवर्तते विनापि शीलेन\n    — one who does it as his OFFICE, whether or not it is his\n    bent, which is the interesting case: a man may have the duty\n    without the inclination;\n  तत्साधुकारी यो धात्वर्थं साधु करोति — one who does it WELL.\n  उत्तरत्रैवोदाहरिष्यामः, and 3.2.135 then gives an example under\n  each, so the heading is seen doing work rather than asserted.\n\nSETTLED — ITS EXTENT IS NAMED BY A RULE AND NOT BY A NUMBER:\n  आ क्वेः — as far as the क्विप् of 3.2.177 — and अभिविधौ चायम्\n  आङ्, the आ is inclusive, तेन क्विपोऽप्ययम् अर्थनिर्देशः, so\n  that rule is covered too. The second heading of this pāda after\n  3.2.84's भूते, and the first whose end is given by naming its\n  last rule.\n\nDEBT — 3.2.177 is not codified, so the far end cannot be checked\n  against a real rule. A test asserts the debt.",
    "3.2.135": "SETTLED — तृन्: सर्वधातुभ्यः, after EVERY root, so this is the\n  widest rule of the run and the five after it cut into it.\n  नकारः स्वरार्थः — the न is written for the accent.\n\nSETTLED — and the vṛtti gives an example under EACH of the\n  heading's three senses, which is how the heading is shown to be\n  doing work: तच्छीले कर्ता कटान्, वदिता जनापवादान्; तद्धर्मणि\n  मुण्डयितारः श्राविष्ठायना भवन्ति वधूमूढाम्, उन्नेतारस्\n  तौल्वलायना भवन्ति पुत्रे जाते; तत्साधुकारिणि कर्ता कटम्,\n  गन्ता खेटम्.\n\nSCOPE — five vārttikas: तृन्विधावृत्विक्षु चानुपसर्गस्य gives\n  होता, पोता — and अनुपसर्गस्येति किम्? उद्गाता, प्रतिहर्ता,\n  तृजेव भवति, स्वरे विशेषः, the difference lying in the accent\n  alone; नयतेः षुक् gives नेष्टा; त्विषेर्देवतायाम् gives त्वष्टा;\n  क्षदेश्च नियुक्ते gives क्षत्ता; and छन्दसि तृच्. Recorded.",
    "3.2.136": 'SETTLED — अलंकृञ्निराकृञ्…सहचर इष्णुच्: अलंकरिष्णुः, निराकरिष्णुः,\n  प्रजनिष्णुः, उत्पचिष्णुः, उन्मदिष्णुः, रोचिष्णुः, वर्धिष्णुः,\n  सहिष्णुः, चरिष्णुः.\n\nSCOPE — अलंकृञो मण्डनार्थाद् युचः पूर्वविप्रतिषेधेनेष्णुज्\n  वक्तव्यः: where अलम् + कृ means ADORNING, this affix wins over\n  युच् by पूर्वविप्रतिषेध — a PRIOR rule beating a later one,\n  which is the reverse of the ordinary direction. Recorded rather\n  than codified, since युच् is not yet in the project and there\n  is nothing here for the priority to act against.',
    "3.2.137": 'SETTLED — णेश्छन्दसि: दृषदं धारयिष्णवः, वीरुधः पारयिष्णवः.\n  From the CAUSATIVE stem, and in the Veda.',
    "3.2.138": "SETTLED — भुवश्च: भविष्णुः.\n\nSETTLED — AND IT IS VEDIC TOO. भवतेर्धातोश्छन्दसि विषये: 3.2.137's\n  छन्दसि runs on into this rule and stops only at 3.2.139, which\n  says so itself. The condition was left off the row at first, and\n  the cost was exact: 3.2.138 and 3.2.139 both name भू, they tied\n  on stated conditions, and the earlier row won on table order —\n  so भूष्णुः was lost and only भविष्णुः came out. A running\n  condition that had to be read from the NEXT rule's निवृत्ति.\n\nSETTLED — योगविभाग उत्तरार्थः, split from 3.2.137 for the rule\n  after. And चकारोऽनुक्तसमुच्चयार्थः: the च gathers in what is\n  not named — भ्राजिष्णुना लोहितचन्दनेन.",
    "3.2.139": 'SETTLED — ग्लाजिस्थश्च क्स्नुः: ग्लास्नुः, जिष्णुः, स्थास्नुः, and\n  भूष्णुः by the च. छन्दसीति निवृत्तम् — the Vedic condition that\n  ran from 3.2.137 STOPS here, which is the seventh अनुवृत्ति in\n  this pāda ended by the commentary rather than by the text.\n\nSETTLED — THE MARKER IS ग् AND NOT क्, and the vṛtti draws three\n  consequences from it: गिच् चायं प्रत्ययः, न कित् — तेन स्थ\n  ईकारो न भवति; the ग of 1.1.5 क्क्ङिति च is read as a चर्त्व\n  substitute so no guṇa comes; and 7.2.11 श्र्युकः किति likewise\n  names a ग, so भू takes no augment.\n\nSETTLED — AND THE THREE ARE THEN PUT IN A VERSE:\n  क्स्नोर्गित्त्वान्न स्थ ईकारः क्ङितोरीत्वशासनात् /\n  गुणाभावस्त्रिषु स्मार्यः श्र्युकोऽनिट्त्वं गकोरितोः //\n  A mnemonic standing in for three separate arguments — the first\n  कारिका this project has met in the Kāśikā, and a reminder that\n  the commentary teaches as well as explains.\n\nSCOPE — दंशेश्छन्दस्युपसंख्यानम्: दङ्क्ष्णवः पशवः. Recorded.',
    "3.2.140": 'SETTLED — त्रसिगृधिधृषिक्षिपेः क्नुः: त्रस्नुः, गृध्नुः, धृष्णुः,\n  क्षिप्णुः.',
    "3.2.141": "SETTLED — शमित्यष्टाभ्यो घिनुण्: शमी, दमी, श्रमी, भ्रमी, क्षमी,\n  प्रमादी. इतिशब्द आद्यर्थः, and the group is a stretch of the\n  दिवादि class named by BOTH ITS ENDS — from शमु to मदी — as\n  3.1.140's ज्वलादि was. अष्टाभ्य इति किम्? असिता, the ninth.\n\nSETTLED — THREE MARKERS ON ONE AFFIX, EACH DOING A DIFFERENT JOB,\n  and the vṛtti separates them: घकार उत्तरत्र कुत्वार्थः, the घ\n  for a sound-change in a later rule; उकार उच्चारणार्थः, the उ\n  merely to make the consonant pronounceable and meaning nothing;\n  णकारो वृद्ध्यर्थः, the ण for the strengthening. Three marks,\n  three unrelated purposes, one of them purely mechanical.",
    "3.2.142": "SETTLED — संपृचानुरुधाङ्यमाङ्यस…: संपर्की, अनुरोधी, आयामी,\n  परिसारी, संसर्गी, परिदेवी, परिक्षेपी, दोषी, द्वेषी, द्रोही,\n  योगी, विवेकी, त्यागी, रागी, भागी.\n\nSETTLED — FOUR ROOT AMBIGUITIES SETTLED BEFORE A SINGLE FORM IS\n  GIVEN, which is the vṛtti's habit in every long list: पृची is\n  the रुधादि root and not the तुदादि, लुग्विकरणत्वात् — the\n  तुदादि one loses its class-marker and so could not be told\n  apart; परिदेवि is भ्वादि; क्षिप् is taken in both its classes\n  सामान्येन; युज् likewise, द्वयोरपि ग्रहणम्. And रञ्ज loses its\n  nasal by निपातन.",
    "3.2.143": 'SETTLED — वौ कषलसकत्थस्रम्भः: विकाषी, विलासी, विकत्थी, विस्रम्भी.',
    "3.2.144": 'SETTLED — अपे च लषः: अपलाषी, and विलाषी. चकाराद् वौ च — the च\n  carries वि down from 3.2.143, so one rule borrows the preverb\n  of the rule before it rather than restating it.',
    "3.2.145": 'SETTLED — प्रे लपसृद्रुमथवदवसः: प्रलापी, प्रसारी, प्रद्रावी,\n  प्रमाथी, प्रवादी, प्रवासी.\n\nSETTLED — and वस् is वस निवासे and not the root meaning to\n  clothe, लुग्विकरणत्वात् — the same ground 3.2.142 used for\n  पृची, twice within four rules. A root that loses its\n  class-marker cannot be identified by it, so it cannot be the\n  one a rule names.',
    "3.2.146": "SETTLED — निन्दहिंसक्लिशखादविनाश…: निन्दकः, हिंसकः, क्लेशकः,\n  खादकः, विनाशकः, परिवादकः, असूयकः. पञ्चम्यर्थे प्रथमा — the\n  nominative standing for an ablative.\n\nSETTLED — A ज्ञापक THAT BEARS ON THE WHOLE HEADING, and the\n  argument is worth having whole. ण्वुलैव सिद्धे वुञ्विधानं\n  ज्ञापनार्थम्: ण्वुल् would have produced the very same form, so\n  prescribing वुञ् cannot be for the form's sake and must be\n  telling us something else — ताच्छीलिकेषु वासरूपन्यायेन तृजादयो\n  न भवन्ति. Inside this heading 3.1.94's वासरूप does NOT let the\n  other affixes stand alongside.\n\nSETTLED — 3.1.94 IS CODIFIED, and its own notes record that it\n  suspends the अपवाद principle for the कृत् section at large.\n  This heading then suspends the suspension. Nothing in the code\n  had to change — the resolver already gives one answer — but the\n  reason it gives one is now the text's and not the table's.",
    "3.2.147": 'SETTLED — देविक्रुशोश्चोपसर्गे: आदेवकः, परिदेवकः, आक्रोशकः,\n  परिक्रोशकः. उपसर्ग इति किम्? देवयिता, क्रोष्टा.\n\nSETTLED — the rule wants A preverb without naming WHICH, where\n  3.2.143 to 3.2.145 each named one. So the condition needed a\n  field of its own rather than a list.',
    "3.2.148": 'SETTLED — चलनशब्दार्थादकर्मकाद् युच्: चलनः, चोपनः; and of sound,\n  शब्दनः, रवणः. अकर्मकादिति किम्? पठिता विद्याम् — with an object\n  the rule does not reach.\n\nSETTLED — the rule names no root at all: it reaches whatever\n  MEANS motion or sound, which is a condition on the sense and\n  not on the word.',
    "3.2.149": 'SETTLED — अनुदात्तेतश्च हलादेः: वर्तनः, वर्धनः.\n\nSETTLED — THREE CONDITIONS AND THE VṚTTI ASKS AFTER EACH:\n  अनुदात्तेत इति किम्? भविता — a root not marked with the\n  anudātta; हलादेरिति किम्? एधिता — one not beginning with a\n  consonant; and आदिग्रहणं किम्? जुगुप्सनः, मीमांसनः — the word\n  आदि is there so that a root counts as consonant-initial even\n  where a reduplication or a सन् stands in front of it, the\n  question being about the ROOT and not the stem.\n  अकर्मकादित्येव, carried down: वसिता वस्त्रम्.',
    "3.2.150": "SETTLED — जुचङ्क्रम्यदन्द्रम्यसृगृधिज्वलशुचलषपतपदः: जवनः,\n  चङ्क्रमणः, सरणः, गर्धनः, ज्वलनः, शोचनः, पतनः. जु इति सौत्रो\n  धातुः — a root the sūtra supplies itself, as 3.1.138's साति was.\n\nSETTLED — THE SAME ज्ञापक AGAIN, WITH A CAVEAT ADDED.\n  चलनार्थानां पदेश्च ग्रहणं सकर्मकार्थम् — naming पद् is for the\n  transitive case, which 3.2.148 had shut out. And others read it\n  as a second ज्ञापक: ताच्छीलिकेषु मिथो वासरूपविधिर् नास्ति, तेन\n  अलंकृञस् तृन् न भवति.\n  Then the caveat that matters: प्रायिकं चैतद् ज्ञापकम्, क्वचित्\n  समावेश इष्यत एव — गन्ता खेटं विकत्थनः. The suspension is\n  GENERAL and not absolute.",
    "3.2.151": 'SETTLED — क्रुधमण्डार्थेभ्यश्च: क्रोधनः, रोषणः, मण्डनः, भूषणः.\n  The rule names two roots and reaches whatever MEANS what they\n  mean — which is why रोषण and भूषण stand beside the two named,\n  and why the condition is codified as a sense rather than a list.',
    "3.2.152": "SETTLED — न यः: क्नूयिता, क्ष्मायिता. पूर्वेण प्राप्तः\n  प्रतिषिध्यते — what 3.2.149 would have given a य-final root is\n  refused.\n\nSETTLED — and it does not thereby govern: what those roots take\n  is 3.2.135's तृन्, which is the form the vṛtti gives, so that\n  rule is named and this one rides on `blocked_by`. The fourth\n  प्रतिषेध of the pāda to be handled this way, after 3.2.23,\n  3.2.113 and 3.2.9.",
    "3.2.153": 'SETTLED — सूददीपदीक्षश्च: सूदिता, दीपिता, दीक्षिता.\n  अनुदात्तेत्त्वात् प्राप्तः प्रतिषिध्यते.\n\nSETTLED — AND THE VṚTTI ASKS WHY A REFUSAL IS NEEDED AT ALL,\n  since 3.2.167 gives दीप् a र of its own which would have\n  displaced the युच् anyway: स एव बाधको भविष्यति, किं\n  प्रतिषेधेन? The answer turns on वासरूप — वासरूपेण युजपि\n  प्राप्नोति, the युच् could still have stood BESIDE it. So the\n  refusal is needed exactly because the suspension of वासरूप is\n  प्रायिक and not absolute, and the vṛtti says so in the same\n  breath: तथा च समावेशो दृश्यते — कम्रा युवतिः beside कमना\n  युवतिः, कम्प्रा शाखा beside कम्पना शाखा.\n\nSCAR — सूदेर् युचि प्रतिषिद्धे कथं मधुसूदनो रिपुसूदन इति? Three\n  answers are offered and NONE is settled: that the refusal is\n  अनित्य by योगविभाग; or that those words are नन्द्यादि; or that\n  they are ल्युडन्त by 3.3.113 — which is not codified, and is\n  the same uncodified rule 3.2.53 had to lean on. Recorded as a\n  scar because the commentary itself declines to choose.',
    "3.2.154": 'SETTLED — लषपतपदस्थाभूवृषहनकमगमशॄभ्य उकञ्: अपलाषुकं\n  वृषलसंगतम्, प्रपातुका गर्भा भवन्ति, उपपादुकं सत्त्वम्, कामुका\n  एनं स्त्रियो भवन्ति, प्रवर्षुकाः पर्जन्याः.\n\nSETTLED — every example here is a WHOLE SENTENCE rather than a\n  bare word, which is unusual enough to note: these forms are\n  being quoted from usage rather than built to order, and the\n  sentence is what shows the sense the affix carries.',
    "3.2.155": "SETTLED — जल्पभिक्षकुट्टलुण्टवृङः षाकन्: जल्पाकः, भिक्षाकः,\n  कुट्टाकः, लुण्टाकः, वराकः.\n\nSETTLED — षकारो ङीषर्थः: the ष is written for the FEMININE,\n  वराकी — a marker doing its work in another adhyāya, as 3.2.16's\n  ट did for कुरुचरी and 3.2.12's अच् did in the feminine. The\n  third time this pāda chooses a marker for what a later rule\n  will do with it.",
    "3.2.156": 'SETTLED — प्रजोरिनिः: प्रजवी, प्रजविनौ.',
    "3.2.157": "SETTLED — जिदृक्षिविश्रीण्वमाव्यथाभ्यमपरिभूप्रसूभ्यश्च: जयी, दरी,\n  क्षयी, विश्रयी, वमी, अव्यथी, परिभवी, प्रसवी.\n  Two roots settled before any form is given, as this pāda's long\n  lists always are: क्षि is taken in both its senses, and प्रसू is\n  षू प्रेरणे.",
    "3.2.158": 'SETTLED — स्पृहिगृहिपतिदयिनिद्रातन्द्राश्रद्धाभ्य आलुच्:\n  स्पृहयालुः, दयालुः, निद्रालुः, श्रद्धालुः.\n\nSETTLED — three of the seven are not roots of a list at all but\n  COMPOUNDS the sūtra fixes: निद्रा and तन्द्रा are द्रा with नि,\n  श्रद्धा is धा with श्रत्, and तदो नकारान्तता च निपात्यते. So a\n  rule that looks like a root-list is partly a निपातन.\n\nSCOPE — आलुचि शीङो ग्रहणं कर्तव्यम्: शयालुः. Codified into the\n  list, the vārttika only adding a member.',
    "3.2.159": "SETTLED — दाधेट्सिशदसदो रुः: दारुः, धारुर्वत्सो मातरम्, सेरुः,\n  शद्रुः, सद्रुः.\n  And 2.3.69's ban on the genitive does not reach these —\n  उकारप्रश्लेषात्, the rule's own wording admitting a उ these\n  affixes do not answer to. Cited, not called: that rule acts on\n  the finished construction.",
    "3.2.160": 'SETTLED — सृघस्यदः क्मरच्: सृमरः, घस्मरः, अद्मरः.',
    "3.2.161": 'SETTLED — भञ्जभासमिदो घुरच्: भङ्गुरं काष्ठम्, भासुरं ज्योतिः,\n  मेदुरः पशुः. घित्त्वात् कुत्वम् — the ghost घ is what gives the क.\n\nSETTLED — भञ्जेः कर्मकर्तरि प्रत्ययः, स्वभावात्: for that root the\n  affix falls in the कर्मकर्तृ sense, and NOT because the rule says\n  so — BY THE NATURE OF THE THING, wood being broken rather than\n  breaking. A justification from how the world is rather than from\n  the text, which the next rule uses again.',
    "3.2.162": 'SETTLED — विदिभिदिच्छिदेः कुरच्: विदुरः पण्डितः, भिदुरं काष्ठम्,\n  छिदुरा रज्जुः.\n  विद् is the one meaning to KNOW and not the one meaning to get —\n  again स्वभावात्, the second time in two rules a question is\n  settled from the nature of the case rather than from anything\n  stated. भिदिच्छिद्योः कर्मकर्तरि प्रयोगः.\n\nSCOPE — व्यधेः संप्रसारणं कुरच् च: विधुरः. Codified into the list.',
    "3.2.163": 'SETTLED — इण्नश्जिसर्तिभ्यः क्वरप्: इत्वरः and इत्वरी, नश्वरः,\n  जित्वरः, सृत्वरः. पकारस्तुगर्थः, the प for an augment; and\n  7.2.8 नेड् वशि कृति keeps the इट् out. Both cited, neither\n  called — they act after the affix is chosen.',
    "3.2.164": 'SETTLED — गत्वरश्च: गत्वरः, गत्वरी. A निपातन INSIDE the table\n  rather than outside it, and the split is exact: what is fixed is\n  the loss of the nasal, गमेर् अनुनासिकलोपः, while the affix\n  itself is prescribed as everywhere else. The same division\n  3.2.71 made — धातूपपदसमुदाया निपात्यन्ते, प्रत्ययस्तु विधीयत एव.',
    "3.2.165": 'SETTLED — जागुरूकः: जागरूकः.',
    "3.2.166": 'SETTLED — यजजपदशां यङः: यायजूकः, जञ्जपूकः, दन्दशूकः. The affix\n  comes after the यङन्त STEM and not the bare root, so the stem\n  must be built before this rule can reach it — the first\n  condition in this run about something made earlier rather than\n  about the root itself.',
    "3.2.167": "SETTLED — नमिकम्पिस्म्यजसकमहिंसदीपो रः: नम्रं काष्ठम्, कम्प्रा\n  शाखा, स्मेरं मुखम्, अजस्रं जुहोति, कम्रा युवतिः, हिंस्रं रक्षः,\n  दीप्रं काष्ठम्. अजस्र is जसु with नञ् before it, of an act going\n  on without cease.\n\nSETTLED — THIS IS THE RULE 3.2.153 NAMED. That sūtra asked whether\n  its own refusal was needed when this one would have displaced\n  the युच् anyway, and answered that वासरूप could still have let\n  the two stand together. And कम्रा and कम्प्रा — this rule's own\n  forms — are the pair cited there as standing beside कमना and\n  कम्पना. So the two rules corroborate each other across fourteen\n  sūtras, and the suspension of वासरूप is shown to be प्रायिक\n  from both ends.",
    "3.2.168": 'SETTLED — सनाशंसभिक्ष उः: चिकीर्षुः, जिहीर्षुः, आशंसुः, भिक्षुः.\n\nSETTLED — सन् IS THE AFFIX AND NOT THE ROOT षण्, and the vṛtti\n  gives TWO grounds without choosing between them: अनभिधानाद्\n  व्याप्तिन्यायाद् वा — either because reading it as the root\n  would produce no word anyone uses, or by the principle that the\n  wider reading is taken. Recorded as offered.\n  आङः शसि इच्छायाम् is meant and not शंस् in the sense of praise.',
    "3.2.169": 'SETTLED — विन्दुरिच्छुः: वेदनशीलो विन्दुः, एषणशील इच्छुः. Both\n  are fixed — विदेर् नुमागमः for the one, इषेश् छत्वम् for the\n  other, and the उ for both.',
    "3.2.170": 'SETTLED — क्याच्छन्दसि: मित्रयुः, स्वेदयुः, सुम्नयुः.\n  छन्दसीति किम्? मित्रीयिता.\n\nSETTLED — क्य is क्यच्, क्यङ् and क्यष् TAKEN TOGETHER, सामान्येन\n  निर्देशः: one syllable standing for three affixes at once. Not a\n  pratyāhāra — no marker span — but the same economy by another\n  means. And 7.4.35 keeps the vowel short.',
    "3.2.171": "SETTLED — आदृगमहनजनः किकिनौ लिट् च: पपिः सोमं ददिर्गाः, ततुरिम्,\n  जगुरिः, जग्मिर्युवा, जघ्निर्वृत्रम्. लिड्वच्च तौ भवतः, they\n  behave as लिट् does.\n\nSETTLED — AND THE VṚTTI ASKS WHY THEY ARE MARKED कित् AT ALL,\n  since 1.2.5 असंयोगाल्लिट् कित् gives that already: because\n  7.4.11 ऋच्छत्यृताम् prescribes a guṇa in the perfect precisely\n  where a prohibition would otherwise reach, तस्यापि बाधनार्थं\n  कित्त्वम् — the marking is there to defeat THAT. A मार्कर\n  written to survive a specific later rule, which is the same\n  shape as 3.1.141's श्यै and 3.2.44's अण्.\n\nSETTLED — the तकार of आत् is मुखसुखार्थ and not a तपर, so it does\n  not restrict the vowel's length: a letter present for ease of\n  pronunciation and meaning nothing, as 3.2.141's उ was.\n\nSCOPE — three vārttikas widen it: किकिनावुत्सर्गः (सेदिः, नेमिः),\n  भाषायां धाञ्कृञ्सृजनिगमिनमिभ्यः (दधिः, चक्रिः, जग्मिः), and\n  सहिवहिचलिपतिभ्यो यङन्तेभ्यः (सासहिः, वावहिः). Recorded.",
    "3.2.172": 'SETTLED — स्वपितृषोर्नजिङ्: स्वप्नक्, तृष्णक्. छन्दसीति निवृत्तम्\n  — the Vedic condition that ran through 3.2.170 and 3.2.171 stops\n  here, the eighth अनुवृत्ति in this pāda ended by the commentary.\n  SCOPE: धृषेश्च, धृष्णक्.',
    "3.2.173": 'SETTLED — शॄवन्द्योरारुः: शरारुः, वन्दारुः.',
    "3.2.174": 'SETTLED — भियः क्रुक्लुकनौ: भीरुः, भीलुकः, both affixes standing.\n  SCOPE: क्रुकन्नपि वक्तव्यः gives a third, भीरुकः.',
    "3.2.175": 'SETTLED — स्थेशभासपिसकसो वरच्: स्थावरः, ईश्वरः, भास्वरः,\n  पेस्वरः, विकस्वरः.\n\nSETTLED — and स्था is named by 3.2.139 as well, which gives it\n  क्स्नु: स्थास्नुः and स्थावरः both stand, and the vṛtti gives\n  each under its own rule. Another समावेश, and the reason\n  `wants` was added to this entry point — with two rules naming\n  one root and neither wrong, the caller has to say which affix\n  is being asked after.',
    "3.2.176": 'SETTLED — यश्च यङः: यायावरः. The second rule of the run to want a\n  यङन्त stem, after 3.2.166.',
    "3.2.177": "SETTLED — भ्राजभासधुर्विद्युतोर्जिपॄजुग्रावस्तुवः क्विप्: विभ्राट्,\n  भाः, धूः, विद्युत्, ऊर्क्, पूः, जूः, ग्रावस्तुत्.\n  जवतेर् दीर्घश्च निपात्यते.\n\nSETTLED — AND IT CLOSES AN ARGUMENT BEGUN THIRTY-ONE RULES BACK.\n  किमर्थमिदमुच्यते, यावता अन्येभ्योऽपि दृश्यन्ते, क्विप् च इति\n  क्विप् सिद्ध एव? — 3.2.75 and 3.2.76 give क्विप् already, so why\n  again? ताच्छीलिकैर् बाध्यते, वासरूपविधिर् नास्तीत्युक्तम्: the\n  affixes of this heading would DISPLACE that general क्विप्, and\n  because वासरूप is suspended here it could not have stood beside\n  them. The rule exists on the strength of the ज्ञापक at 3.2.146.\n  And the qualification comes once more: अथ तु प्रायिकम् एतत्,\n  ततस् तस्यैवायं प्रपञ्चः — if the suspension is only general,\n  then this is simply that rule worked out.\n\nSETTLED — AND IT IS THE FAR END OF 3.2.134's HEADING. आ क्वेः\n  named this rule rather than a number, and the आ is inclusive, so\n  codifying it closes the span from both sides. The DEBT recorded\n  at 3.2.134 is paid, and the test asserting it goes red.",
    "3.2.178": "SETTLED — अन्येभ्योऽपि दृश्यते: युक्, छित्, भित्. The pāda's\n  FOURTH open rule, after 3.2.75, 3.2.76 and 3.2.101, and held to\n  attested forms as those are.\n\nSETTLED — BUT ITS दृश्यते DOES A DIFFERENT JOB FROM THEIRS. At\n  3.2.75 the vṛtti read the word प्रयोगानुसरणार्थम्, so that the\n  rule follows usage rather than manufacturing forms. Here it is\n  विध्यन्तरोपसंग्रहार्थम् — to GATHER IN OTHER OPERATIONS beyond\n  the affix: क्वचिद् दीर्घः, क्वचिद् द्विर्वचनम्, क्वचित्\n  संप्रसारणम्, क्वचिद् असंप्रसारणम्. One word doing two different\n  jobs a hundred sūtras apart, and only the commentary tells them\n  apart.\n\nSCOPE — the operations are then given in a verse: वचि, प्रच्छि,\n  आयतस्तु, कटप्रु and श्री take the long vowel and no संप्रसारण\n  (वाक्, शब्दप्राट्, कटप्रूः, श्रीः); द्युति, गमि and जुहोति\n  reduplicate (दिद्युत्, जगत्, जुहूः); दृ takes a short vowel and\n  reduplication (ददृत्); ध्यै takes संप्रसारण (धीः).\n  And the vṛtti catches a redundancy in its own verse:\n  जुग्रहणेनात्र नार्थः, भ्राजादिसूत्र एव गृहीतत्वात् — जु was\n  named at 3.2.177 already.",
    "3.2.179": 'SETTLED — भुवः संज्ञान्तरयोः: विभूर्नाम कश्चित्, a name; and\n  प्रतिभूः in the sense of BETWEEN.\n  The second sense is glossed by the situation rather than by a\n  synonym: धनिकाधमर्णयोरन्तरे यस्तिष्ठति स प्रतिभूरुच्यते — one\n  who stands between creditor and debtor, a surety. A definition\n  by circumstance, which reads oddly in a grammar and is exactly\n  what makes the word intelligible.',
    "3.2.180": "SETTLED — विप्रसम्भ्यो ड्वसंज्ञायाम्: विभुः सर्वगतः, प्रभुः\n  स्वामी, संभुर्जनिता.\n  असंज्ञायामिति किम्? विभूर्नाम कश्चित् — which is 3.2.179's own\n  example. So the two rules divide ONE WORD between them by\n  whether it is being used as a name: विभुः the widespread, विभूः\n  somebody called Vibhū.\n\nSCOPE — डुप्रकरणे मितद्र्वादिभ्य उपसंख्यानम्: मितद्रुः, शंभुः.",
    "3.2.181": 'SETTLED — धः कर्मणि ष्ट्रन्: धयन्ति तां दधति वा भैषज्यार्थम् इति\n  धात्री — said both of a wet-nurse and of the myrobalan, one\n  word covering a person and a plant because the same thing is\n  done to each.\n  षकारो ङीषर्थः — the ष for the feminine, the fourth marker in\n  this pāda written for what another rule will do with it.',
    "3.2.182": 'SETTLED — दाम्नीशसयुयुजस्तुतुदसिसिचमिहपतदशनहः करणे: दात्रम्,\n  नेत्रम्, शस्त्रम्, योत्रम्, योक्त्रम्, स्तोत्रम्, तोत्त्रम्,\n  सेत्रम्, सेक्त्रम्, मेढ्रम्, पत्त्रम्, दंष्ट्रा, नद्ध्री.\n  Thirteen roots, each naming the thing an act is done WITH.\n\nSETTLED — A ज्ञापक FROM HOW ONE ROOT IS SPELT IN THE SŪTRA:\n  दंशेरनुनासिकलोपेन निर्देशो ज्ञापनार्थः — the rule writes दश and\n  not दंश, and that spelling tells us क्ङितोऽन्यस्मिन्नपि\n  प्रत्यये नलोपः क्वचिद् भवति, the nasal may drop before affixes\n  other than कित् and ङित् ones. तेन ल्युट्यपि भवति, दशनम्. A\n  spelling in one rule licensing an operation in another — the\n  same kind of evidence 3.2.111 and 3.2.126 drew from compound\n  form, now drawn from orthography.',
    "3.2.183": "SETTLED — हलसूकरयोः पुवः: हलस्य पोत्रम्, सूकरस्य पोत्रम्, मुखम्\n  उच्यते — the ploughshare and the boar's snout, one word for\n  both.\n  The condition is on what the instrument is PART OF, which no\n  rule of this pāda had asked before: not what it does, not what\n  it is called, but what it belongs to.",
    "3.2.184": 'SETTLED — अर्तिलूधूसूखनसहचर इत्रः: अरित्रम् an oar, लवित्रम् a\n  sickle, धवित्रम् a fan, सवित्रम्, खनित्रम् a spade, सहित्रम्,\n  चरित्रम्.',
    "3.2.185": 'SETTLED — पुवः संज्ञायाम्: दर्भः पवित्रम्, बर्हिष्पवित्रम्.\n  समुदायेन चेत् संज्ञा गम्यते — the NAME is carried by the whole,\n  the fourth समुदायोपाधि of this pāda after 3.2.80, 3.2.92 and\n  3.2.99.',
    "3.2.186": 'SETTLED — कर्तरि चर्षिदेवतयोः, यथासंख्यम् — and the pairing is\n  crosswise between a KĀRAKA and a kind of being, which is a\n  shape the pāda has not used before: ऋषौ करणे, देवतायां कर्तरि.\n  Of a seer the word names the MEANS — पूयतेऽनेनेति पवित्रोऽयम्\n  ऋषिः; of a deity the DOER — अग्निः पवित्रं स मा पुनातु. One\n  form, two readings, and which is meant depends on what it is\n  said of.',
    "3.2.187": 'SETTLED — ञीतः क्तः: मिन्नः, क्ष्विण्णः, धृष्टः, of roots marked\n  ञि in उपदेश.\n\nSETTLED — AND IT EXCEPTS A RULE OF THIS SAME PĀDA. भूते निष्ठा\n  विहिता वर्तमाने न प्राप्नोतीति विधीयते: 3.2.102 gave the affix\n  named निष्ठा for the PAST, so it would not have reached the\n  present, and this rule is stated to supply it. Eighty-five\n  sūtras apart, and the later one names the earlier.\n  Codified from beside 3.2.102 rather than from the affix table,\n  since the question — when does क्त come — is the one that rule\n  answers differently.',
    "3.2.188": "SETTLED — मतिबुद्धिपूजार्थेभ्यश्च: राज्ञां मतः, राज्ञामिष्टः,\n  राज्ञां बुद्धः, राज्ञां ज्ञातः, राज्ञां पूजितः,\n  राज्ञामर्चितः. मतिरिच्छा, बुद्धिर्ज्ञानम्, पूजा सत्कारः — the\n  rule reaches BY MEANING and names no root, so words beyond the\n  vṛtti's own are covered.\n\nSCOPE — अनुक्तसमुच्चयार्थश्चकारः, and the vṛtti then supplies a\n  long list in two verses — words of pleasing, guarding, bearing,\n  restraint and the rest, all to be taken in the present — with a\n  prose tail adding सुप्तः, शयितः, आशितः, लिप्तः, तृप्तः. Two of\n  the listed words are marked off from the others: कष्टः belongs\n  to the FUTURE and अमृतः is पूर्ववत्, so the list is not uniform\n  and the verses cannot be read as a flat set.\n\nSETTLED — this is the last sūtra of the pāda, and the Kāśikā\n  closes here with its colophon.",
}

#: What each rule of this run asks of a rule already codified.
#:
#: 1.4.59 gives 3.2.3 and 3.2.8 their अनुपसर्ग. That is the whole list,
#: and 1.1.71 was on it until the guard refused it: आत् is a PLAIN
#: SOUND and not a pratyāhāra, so nothing here forms a span and 1.1.71
#: is never reached. The neighbouring runs declare it because हल् and
#: अच् and इक् are spans; this one asks only whether the last sound is
#: आ. A declaration made by reflex rather than by reading the call.
#:
#: 3.1.92 उपपदमतिङ् is what makes the companion a companion at all and
#: every rule of the run needs it — but it is not declared here,
#: because nothing in this module CALLS it: what the resolver takes is
#: already an उपपद, asserted by the caller. A citation, and the
#: registration notes are where a citation belongs.
#:
#: 3.2.7 likewise cites 2.4.54 in prose without calling it — ख्या
#: arrives as the root name, the substitution already made.
#:
#: 3.2.21 to 3.2.28 declare NOTHING, and that is the honest
#: reading rather than an oversight. 3.2.28 cites 3.4.113 for what
#: its श buys and 3.2.21 cites the adhyāya-8 rules its भास्करः
#: escapes, but both consequences happen downstream of choosing
#: the affix, which is all this module does. Declaring them would
#: have made the guard walk for a call that is not there — the
#: same mistake 3.2.3's 1.1.71 was.
_UPAPADA_REUSES = {
    # 3.2.3 wants a root ending in आ, and ह्वेञ् and वेञ् end in
    # ए where the धातुपाठ taught them. 6.1.45 आदेच
    # उपदेशेॎशिति is what makes them आ-final, and its
    # प्रसज्यप्रतिषेध is what puts the आ there BEFORE the
    # affix arrives to ask. `ends_in_a` calls it, so the edge is
    # code calling code and not a citation.
    "3.2.3": ("1.4.59", "6.1.45"),
    "3.2.8": ("1.4.59",),
    # 3.2.43 alone reaches what ENDS in one of its named words, and the
    # vṛtti says which rule does that: उपपदविधौ भयादिग्रहणं
    # तदन्तविधिं प्रयोजयति. 1.1.72 is codified, so अभयंकरः comes from
    # asking it rather than from a suffix test written here.
    "3.2.43": ("1.1.72",),
    # 3.2.102 निष्ठा names an affix rather than adding one, and
    # WHICH affixes bear the name is 1.1.26 क्तक्तवतू निष्ठा's.
    # That rule is codified, so it is asked: the two are not
    # retyped here, and a refusal from it comes back nameless
    # because 1.1.26 is what withheld the name.
    "3.2.102": ("1.1.26",),
}

#: The sūtras answered ONLY from the fixed-word lookup. 3.2.5 and
#: 3.2.59 are deliberately absent though both supply fixed words:
#: each has a regular provision of its own as well, so each is
#: registered against the table and contributes to the lookup
#: besides. 3.2.59 is the first sūtra that had to be both.
_FIXED_ONLY = ("3.2.26", "3.2.37", "3.2.55", "3.2.109")

#: 3.2.102 names an affix rather than adding one, and 3.2.105-108
#: substitute for लिट् rather than adding to a root. Neither shape
#: fits the table, so each has its own entry point.
_SAMJNA = ("3.2.102",)
_LIT = ("3.2.105", "3.2.106", "3.2.107", "3.2.108")

#: 3.2.110-122 choose a tense-ENDING rather than adding a कृत्
#: affix, and their conditions are about time and about the
#: situation of speaking. The sixth kind of rule this pāda needs.
_LAKARA = tuple("3.2.%d" % _n for _n in range(110, 123)) + (
    # 3.2.123 वर्तमाने लट् is where 3.2.84's भूते heading stops,
    # so it is the first लकार rule outside the past.
    "3.2.123",
)

#: 3.2.124-133 put शतृ and शानच् where लट् would have stood —
#: a substitution, as 3.2.105-108 are for लिट्.
_LAT = tuple("3.2.%d" % _n for _n in range(124, 134)
             if _n != 127)

#: 3.2.127 तौ सत् names the pair and adds nothing, as 3.2.102
#: named निष्ठा. Two संज्ञā rules now, each with its own entry
#: point since they confer different names.
_SAT = ("3.2.127",)

#: 3.2.187 and 3.2.188 give क्त in the PRESENT, excepting 3.2.102,
#: and 3.2.187's vṛtti names that rule as the reason they exist.
#: They answer from beside it, not from the affix table.
_PRESENT_KTA = ("3.2.187", "3.2.188")

_PRESENT_KTA_LINE = (
    'kta_in_present(nit=..., sense=...) -> whether क्त comes of a PRESENT '
    'act, against 3.2.102.'
)

#: 3.2.134 आ क्वेः is the pāda's second heading, and the first
#: whose extent is given by NAMING its last rule rather than by a
#: number. 3.2.135-140 are the affixes under it.
_TACCHILA_HEAD = ("3.2.134",)
_TACCHILA = tuple("3.2.%d" % _n for _n in range(135, 187))

_TACCHILA_HEAD_LINE = (
    'tacchila_heading(sutra_id=...) -> what the heading covers, and whether '
    'a given sūtra falls under it.'
)

_TACCHILA_LINE = (
    'tacchila_affix(root, wants=..., causative=..., chandasi=..., '
    'upasarga=..., '
    'akarmaka=..., anudattet=..., hal_adi=..., sense=..., y_final=...) '
    '-> which affix comes of a doer who acts by habit, by office or well.'
)

_LAT_LINE = (
    'lat_substitute(root, aprathama=..., sambodhana=..., '
    'lakshana_hetu=..., sense=..., akrcchri=..., amitra=..., yajna=...) '
    '-> what stands in place of लट्, and by which rule.'
)

_SAT_LINE = (
    'sat_samjna(affix) -> whether the affix bears the name सत्.'
)

_LAKARA_LINE = (
    'lakara_for(beside=..., anadyatana=..., paroksa=..., question=..., '
    'recent=..., answer=..., sakanksa=..., with_yad=...) -> which '
    'tense-ending comes, and by which rule.'
)

_SAMJNA_LINE = (
    'nistha(affix, past=...) -> whether the affix bears the name निष्ठा '
    'and so comes where the act is past.'
)

_LIT_LINE = (
    'lit_substitute(root, chandasi=...) -> what stands in place of लिट्, '
    'and by which rule.'
)

#: 3.2.84 भूते is an अधिकार: it adds no affix and puts every rule
#: as far as 3.2.122 under a condition none of them states. Its own
#: entry point reports the extent, as 3.1's four headings do.
_HEADING_LINE = (
    'bhute_heading(sutra_id=...) -> what भूते covers, and whether a given '
    'sūtra falls under it.'
)

_NIPATANA_LINE = (
    'nipatana(word) -> a form the grammar fixes outright, given as '
    'it stands, with what the vṛtti says is being fixed in it.'
)

#: Which entry point answers for which rules, and the line that
#: describes it — stated ONCE per kind. These branches used to be two
#: parallel if/elif chains, function and description chosen separately,
#: which had to be kept in the same order by hand: a rule could get one
#: entry point with another's description and nothing would catch it.
#:
#: Order matters only in that the first match wins, and the sets are
#: disjoint — which `test_astadhyayi_pada_close.py` asserts as a
#: partition of the registered rules, not as a count of the kinds.
_DISPATCH = (
    (("3.2.84",), bhute_heading, _HEADING_LINE),
    (_LAKARA, lakara_for, _LAKARA_LINE),
    (_LAT, lat_substitute, _LAT_LINE),
    (_TACCHILA_HEAD, tacchila_heading, _TACCHILA_HEAD_LINE),
    (_TACCHILA, tacchila_affix, _TACCHILA_LINE),
    (_SAT, sat_samjna, _SAT_LINE),
    (_PRESENT_KTA, kta_in_present, _PRESENT_KTA_LINE),
    (_SAMJNA, nistha, _SAMJNA_LINE),
    (_LIT, lit_substitute, _LIT_LINE),
    # 3.2.26 and the other निपातन: what they state is not reachable by
    # any condition, so they answer from their own entry point rather
    # than from the table. The same split the कृत्य run made.
    (_FIXED_ONLY, nipatana, _NIPATANA_LINE),
)

for _sutra, _notes in _UPAPADA_RULES.items():
    _apply, _line = upapada_affix, _UPAPADA_LINE
    for _which, _fn, _describes in _DISPATCH:
        if _sutra in _which:
            _apply, _line = _fn, _describes
            break
    register(
        _sutra,
        apply=_apply,
        codification=_line,
        notes=_notes,
        reuses=_UPAPADA_REUSES.get(_sutra, ()),
    )
